window.DYMEK_INDEX=[{"t": "Home", "u": "index.html", "d": "Advanced equipment and engineering support for Asia’s precision industries.", "c": "Page", "k": "dymek distributor asia", "f": true}, {"t": "Semiconductor Manufacturing & Advanced Packaging", "u": "semiconductor-manufacturing-advanced-packaging.html", "d": "Wafer processing, hybrid bonding, advanced packaging, metrology, failure analysis and fab support equipment for R&D, pilot lines and volume manufacturing across Asia.", "c": "Industry", "k": "Wafer Processing & Device Fabrication Advanced Packaging & Assembly Metrology, Inspection & Failure Analysis Manufacturing Data & Yield Analytics Equipment Service & Fab Support", "f": true}, {"t": "Wafer Processing & Device Fabrication", "u": "semiconductor-manufacturing-advanced-packaging.html#wafer-processing-device-fabrication", "d": "Lithography and resist processing, wafer bonding and layer transfer, plasma etch and deposition, thermal processing, cleaning, wafer separation and pr", "c": "Semiconductor & Advanced Packaging", "k": "Lithography and resist processing, wafer bonding and layer transfer, plasma etch and deposition, thermal processing, cleaning, wafer separation and precision laser processing. Process-control metrology can be added around each step for silicon, MEMS, compound semiconductors, SiC/GaN power devices, sensors and other specialty wafers.", "f": false}, {"t": "Advanced Packaging & Assembly", "u": "semiconductor-manufacturing-advanced-packaging.html#advanced-packaging-assembly", "d": "Wafer-to-wafer and die-to-wafer bonding, hybrid bonding, temporary bonding and debonding, thin-wafer handling, precision die placement, flip-chip and ", "c": "Semiconductor & Advanced Packaging", "k": "Wafer-to-wafer and die-to-wafer bonding, hybrid bonding, temporary bonding and debonding, thin-wafer handling, precision die placement, flip-chip and thermocompression assembly, and 2.5D/3D integration. Typical applications are chiplets, HBM, fan-out, SiP, wafer-level and optical packaging.", "f": false}, {"t": "Metrology, Inspection & Failure Analysis", "u": "semiconductor-manufacturing-advanced-packaging.html#metrology-inspection-failure-analysis", "d": "Optical thin-film measurement, automated wafer inspection, X-ray/CT, scanning acoustic microscopy, electrical probing, electron microscopy and surface", "c": "Semiconductor & Advanced Packaging", "k": "Optical thin-film measurement, automated wafer inspection, X-ray/CT, scanning acoustic microscopy, electrical probing, electron microscopy and surface characterization. Failure-analysis workflows can also include fast laser sample preparation before SEM, FIB, TEM or other high-resolution analysis.", "f": false}, {"t": "Manufacturing Data & Yield Analytics", "u": "semiconductor-manufacturing-advanced-packaging.html#manufacturing-data-yield-analytics", "d": "Manufacturing software brings together data from fabrication, metrology, inspection, assembly and test. Use it for yield analytics, defect management,", "c": "Semiconductor & Advanced Packaging", "k": "Manufacturing software brings together data from fabrication, metrology, inspection, assembly and test. Use it for yield analytics, defect management, SPC, wafer and assembly mapping, automated reporting and equipment monitoring. Custom scripts and integrations can handle specialized engineering or reporting workflows.", "f": false}, {"t": "Equipment Service & Fab Support", "u": "semiconductor-manufacturing-advanced-packaging.html#equipment-service-fab-support", "d": "Repair, refurbishment, replacement, upgrades, field service, spare parts and relocation support for selected vacuum pumps, RF generators and matching ", "c": "Semiconductor & Advanced Packaging", "k": "Repair, refurbishment, replacement, upgrades, field service, spare parts and relocation support for selected vacuum pumps, RF generators and matching networks, legacy thermal equipment and related subsystems.", "f": false}, {"t": "Wafer Processing & Device Fabrication", "u": "wafer-processing-device-fabrication.html", "d": "Lithography, wafer bonding, plasma etch and deposition, furnaces, dicing, laser annealing, CMP and thin-film metrology for silicon, MEMS, SiC/GaN and compound semiconductor fabs in Asia.", "c": "Industry", "k": "Lithography & Resist Processing Wafer Bonding, Layer Transfer & Substrate Engineering Plasma Etch, Deposition & Surface Processing Thermal Processing & Furnaces Wafer Separation, Dicing & Laser Processing CMP Process Development & Consumables Process Control & Thin-Film Metrology", "f": false}, {"t": "Lithography & Resist Processing", "u": "wafer-processing-device-fabrication.html#lithography-resist-processing", "d": "We provide lithography and resist-processing solutions for pattern definition at wafer level. Depending on feature size, substrate and production need", "c": "Wafer Processing & Device Fabrication", "k": "We provide lithography and resist-processing solutions for pattern definition at wafer level. Depending on feature size, substrate and production needs, this can include:\nResist coating and developingMask alignment and maskless exposureNanoimprint lithography\nThese technologies support conventional semiconductor patterning. They also suit MEMS, advanced packaging, photonics and other applications that need flexible pattern transfer or non-standard substrates.", "f": false}, {"t": "Wafer Bonding, Layer Transfer & Substrate Engineering", "u": "wafer-processing-device-fabrication.html#wafer-bonding-layer-transfer-substrate-engineering", "d": "Wafer bonding makes it possible to manufacture MEMS, engineered substrates, image sensors, power devices and compound semiconductor structures. These ", "c": "Wafer Processing & Device Fabrication", "k": "Wafer bonding makes it possible to manufacture MEMS, engineered substrates, image sensors, power devices and compound semiconductor structures. These devices rely on permanent or temporary joining of wafers and layers.\nBonding capabilities include fusion/direct and plasma-activated bonding, temporary bonding and debonding, thin-wafer handling, layer transfer and aligned bonding. Low-temperature bonding supports heterogeneous integration of dissimilar semiconductor materials and engineered substrates.\nFor MEMS and sensors, aligned bonding can also create hermetic or high-vacuum cavity encapsula", "f": false}, {"t": "Plasma Etch, Deposition & Surface Processing", "u": "wafer-processing-device-fabrication.html#plasma-etch-deposition-surface-processing", "d": "Plasma processing forms device structures, opens features, deposits functional films and modifies surfaces. We provide equipment for dry etching, plas", "c": "Wafer Processing & Device Fabrication", "k": "Plasma processing forms device structures, opens features, deposits functional films and modifies surfaces. We provide equipment for dry etching, plasma-enhanced deposition and surface treatment on silicon, dielectric, compound semiconductor and other materials.\nApplications include MEMS structures, power devices, sensors, photonic devices, microLEDs and other devices that need controlled anisotropic etching or deposited films.\nVacuum deposition goes beyond conventional metallization. It also covers piezoelectric films for MEMS and BAW/FBAR devices, sensor oxides, contact and barrier layers fo", "f": false}, {"t": "Thermal Processing & Furnaces", "u": "wafer-processing-device-fabrication.html#thermal-processing-furnaces", "d": "Thermal process equipment for oxidation, diffusion, annealing, LPCVD and other high-temperature wafer processes. Configurations suit university and R&", "c": "Wafer Processing & Device Fabrication", "k": "Thermal process equipment for oxidation, diffusion, annealing, LPCVD and other high-temperature wafer processes. Configurations suit university and R&amp;D laboratories as well as production environments.\nThermal processing is used in silicon device fabrication, MEMS, power semiconductors, photovoltaic devices and specialized material systems. Refurbishment and upgrade support may also be available for selected legacy furnaces.", "f": false}, {"t": "Wafer Separation, Dicing & Laser Processing", "u": "wafer-processing-device-fabrication.html#wafer-separation-dicing-laser-processing", "d": "We support wafer separation and dicing for silicon, SiC and other substrates. The process is chosen by material, device structure, edge quality, parti", "c": "Wafer Processing & Device Fabrication", "k": "We support wafer separation and dicing for silicon, SiC and other substrates. The process is chosen by material, device structure, edge quality, particle control, mechanical strength and throughput. Precision laser processing adds local annealing, trimming, scribing and structuring.\nFor power semiconductors, selective laser annealing can form ohmic contacts on SiC while limiting heat impact on structures already built. Similar approaches serve magnetic sensors and other specialty devices.", "f": false}, {"t": "CMP Process Development & Consumables", "u": "wafer-processing-device-fabrication.html#cmp-process-development-consumables", "d": "Chemical mechanical polishing (CMP) needs coordinated control of slurry chemistry, pad condition, downforce, speed and conditioning. We support CMP pr", "c": "Wafer Processing & Device Fabrication", "k": "Chemical mechanical polishing (CMP) needs coordinated control of slurry chemistry, pad condition, downforce, speed and conditioning. We support CMP process development and consumables evaluation for semiconductor, MEMS, compound semiconductor, optical and advanced-material substrates.\nLaboratory-scale systems let you:\nCompare slurries, pads and conditionersOptimize removal rate and uniformityCorrelate friction or process conditions with changes in pad and wafer surfaces before recipes move to production", "f": false}, {"t": "Process Control & Thin-Film Metrology", "u": "wafer-processing-device-fabrication.html#process-control-thin-film-metrology", "d": "Process development and production need reliable measurement of deposited and patterned layers. Optical metrology measures film thickness, refractive ", "c": "Wafer Processing & Device Fabrication", "k": "Process development and production need reliable measurement of deposited and patterned layers. Optical metrology measures film thickness, refractive index, extinction coefficient, reflectance, transmittance and multilayer structures for dielectrics, resists, semiconductor layers and coatings.\nNon-contact 3D and thickness metrology adds process control for patterned photoresist, transparent functional layers and microfabricated features. This includes post-development and pre-etch checks on silicon, GaAs, MEMS, LED and VCSEL structures.\nWafer-level optical metrology also measures flatness, thi", "f": false}, {"t": "Advanced Packaging & Assembly", "u": "advanced-packaging-assembly.html", "d": "Hybrid bonding, wafer-to-wafer and die-to-wafer bonding, temporary bonding/debonding, die placement, thermocompression, optical packaging and package inspection for chiplets, HBM and fan-out.", "c": "Industry", "k": "Wafer-to-Wafer & Die-to-Wafer Bonding Temporary Bonding, Debonding & Thin-Wafer Handling Precision Die Placement & Thermocompression 2.5D, 3D, Chiplets & HBM Optical & Photonic Packaging Package Inspection & Process Control From Assembly Development to Production", "f": false}, {"t": "Wafer-to-Wafer & Die-to-Wafer Bonding", "u": "advanced-packaging-assembly.html#wafer-to-wafer-die-to-wafer-bonding", "d": "We support fusion, direct and hybrid bonding for wafer-to-wafer and die-to-wafer integration. These technologies create fine-pitch electrical and mech", "c": "Advanced Packaging & Assembly", "k": "We support fusion, direct and hybrid bonding for wafer-to-wafer and die-to-wafer integration. These technologies create fine-pitch electrical and mechanical connections between device layers. They are increasingly important for 3D integration, image sensors, logic-memory integration, chiplets and HBM.\nA complete process flow can include surface preparation, cleaning, activation, alignment, bonding and post-bond metrology.", "f": false}, {"t": "Temporary Bonding, Debonding & Thin-Wafer Handling", "u": "advanced-packaging-assembly.html#temporary-bonding-debonding-thin-wafer-handling", "d": "Thin wafers need reliable mechanical support while they are thinned, processed and transferred. We provide temporary bonding and debonding, carrier ha", "c": "Advanced Packaging & Assembly", "k": "Thin wafers need reliable mechanical support while they are thinned, processed and transferred. We provide temporary bonding and debonding, carrier handling and layer-release processes for advanced packaging, power devices and other thin-substrate applications.\nThese processes support backside processing, redistribution layers (RDL), fan-out packaging and other workflows where wafer fragility and warpage must be carefully controlled.", "f": false}, {"t": "Precision Die Placement & Thermocompression", "u": "advanced-packaging-assembly.html#precision-die-placement-thermocompression", "d": "Advanced packages need high-accuracy placement of known-good die onto wafers, interposers or substrates. We support precision die bonding, flip-chip a", "c": "Advanced Packaging & Assembly", "k": "Advanced packages need high-accuracy placement of known-good die onto wafers, interposers or substrates. We support precision die bonding, flip-chip assembly, thermocompression bonding and related placement processes for fine-pitch interconnects and heterogeneous devices.\nApplications range from R&amp;D and low-volume assembly to production systems for multi-die packages and high-density integration.", "f": false}, {"t": "2.5D, 3D, Chiplets & HBM", "u": "advanced-packaging-assembly.html#2-5d-3d-chiplets-hbm", "d": "High-performance computing and AI are speeding up the adoption of chiplet architectures, silicon interposers and vertically stacked memory. We support", "c": "Advanced Packaging & Assembly", "k": "High-performance computing and AI are speeding up the adoption of chiplet architectures, silicon interposers and vertically stacked memory. We support the bonding, alignment, thin-wafer processing and inspection steps these structures require.\nThe same capabilities apply to other high-density packages that combine logic, memory, sensors, RF, photonics or specialty devices in one package.", "f": false}, {"t": "Optical & Photonic Packaging", "u": "advanced-packaging-assembly.html#optical-photonic-packaging", "d": "As optical and electronic functions converge, packaging needs precise alignment between photonic devices, lenses, fiber arrays and electronic componen", "c": "Advanced Packaging & Assembly", "k": "As optical and electronic functions converge, packaging needs precise alignment between photonic devices, lenses, fiber arrays and electronic components. We support optical component placement, fiber-array alignment, lens alignment and related assembly for optical modules, co-packaged optics and optical I/O.\nThese applications combine semiconductor packaging methods with active or passive optical alignment and high-precision motion.\nHigh-precision die placement and optical coupling also support specialty optoelectronic and sensor packages, such as:\nLiDAR emitters and receiversCommercial laser ", "f": false}, {"t": "Package Inspection & Process Control", "u": "advanced-packaging-assembly.html#package-inspection-process-control", "d": "Advanced packages contain buried interfaces that visual inspection cannot always reach. We provide X-ray and CT inspection, scanning acoustic microsco", "c": "Advanced Packaging & Assembly", "k": "Advanced packages contain buried interfaces that visual inspection cannot always reach. We provide X-ray and CT inspection, scanning acoustic microscopy, automated optical inspection and other metrology techniques. They detect voids, delamination, die cracks, underfill defects, Cu-pillar issues, solder defects and other package abnormalities.\nInspection data supports process development, incoming quality control, production monitoring and failure analysis. For targeted root-cause work, laser-based sample preparation can quickly produce large-area package cross-sections. It can also expose regi", "f": false}, {"t": "From Assembly Development to Production", "u": "advanced-packaging-assembly.html#from-assembly-development-to-production", "d": "For specialized packages, we combine custom fixtures, precision motion, handling, machine vision and process software around the core equipment. Proje", "c": "Advanced Packaging & Assembly", "k": "For specialized packages, we combine custom fixtures, precision motion, handling, machine vision and process software around the core equipment. Projects can move from feasibility trials and process integration into semi- or fully automated production.", "f": false}, {"t": "Metrology, Inspection & Failure Analysis", "u": "metrology-inspection-failure-analysis.html", "d": "Thin-film metrology, wafer AOI, X-ray/CT, scanning acoustic microscopy, probing, SEM/TEM, laser sample preparation and yield analytics software for semiconductor and package failure analysis.", "c": "Industry", "k": "Thin-Film & Optical Process Metrology Wafer-Level Automated Optical Inspection X-Ray & CT Inspection Scanning Acoustic Microscopy Electrical, Magnetic & Device Characterization Electron Microscopy & High-Resolution Analysis Laser Sample Preparation for Failure Analysis Manufacturing Data, Yield Analytics & Software From Measurement Development to Production", "f": false}, {"t": "Thin-Film & Optical Process Metrology", "u": "metrology-inspection-failure-analysis.html#thin-film-optical-process-metrology", "d": "Non-contact optical metrology measures film thickness, refractive index, extinction coefficient, reflectance, transmittance and multilayer structures.", "c": "Metrology, Inspection & Failure Analysis", "k": "Non-contact optical metrology measures film thickness, refractive index, extinction coefficient, reflectance, transmittance and multilayer structures. It works across dielectrics, resists, semiconductor layers and transparent films for mapping, uniformity control and production monitoring.\nSmall-spot reflectometry and non-contact 3D/OCT metrology extend this to patterned regions, rough surfaces, transparent films and subsurface interfaces. Examples include photoresist, MEMS, LED, VCSEL and advanced-packaging structures.\nInterferometric surface metrology adds wafer flatness, thickness variation", "f": false}, {"t": "Wafer-Level Automated Optical Inspection", "u": "metrology-inspection-failure-analysis.html#wafer-level-automated-optical-inspection", "d": "Automated optical inspection (AOI) finds particles, scratches, pattern defects, process abnormalities and other visual anomalies. It works on substrat", "c": "Metrology, Inspection & Failure Analysis", "k": "Automated optical inspection (AOI) finds particles, scratches, pattern defects, process abnormalities and other visual anomalies. It works on substrates, bare wafers, patterned wafers and packaged devices.\nAI-assisted defect detection and classification can reduce manual review, improve consistency and link inspection results to process optimization. Systems can be configured for novel materials, compound semiconductors, photonics and MEMS as well as conventional silicon.", "f": false}, {"t": "X-Ray & CT Inspection", "u": "metrology-inspection-failure-analysis.html#x-ray-ct-inspection", "d": "X-ray inspection gives non-destructive access to buried structures inside semiconductor packages and electronic assemblies. We support 2D X-ray, 3D CT", "c": "Metrology, Inspection & Failure Analysis", "k": "X-ray inspection gives non-destructive access to buried structures inside semiconductor packages and electronic assemblies. We support 2D X-ray, 3D CT and automated inline inspection for solder joints, micro-bumps, Cu pillars, TSV-related structures, die attach, package voids and other internal features.\nHigh-resolution systems suit laboratory analysis, process development or production inspection.", "f": false}, {"t": "Scanning Acoustic Microscopy", "u": "metrology-inspection-failure-analysis.html#scanning-acoustic-microscopy", "d": "Acoustic microscopy is especially good at finding planar defects and interface problems inside bonded wafers and packaged devices. Typical findings in", "c": "Metrology, Inspection & Failure Analysis", "k": "Acoustic microscopy is especially good at finding planar defects and interface problems inside bonded wafers and packaged devices. Typical findings include:\nDelamination and voidsNon-bonded interfaces and die cracksUnderfill quality and molding defectsThermal-interface layer issues\nBecause the method is non-destructive, you can use it for process characterization, reliability analysis and production screening.", "f": false}, {"t": "Electrical, Magnetic & Device Characterization", "u": "metrology-inspection-failure-analysis.html#electrical-magnetic-device-characterization", "d": "This includes four-point-probe resistivity, wafer and chip probing, optoelectronic testing and magnetic thin-film measurement for MRAM and sensors. Pr", "c": "Metrology, Inspection & Failure Analysis", "k": "This includes four-point-probe resistivity, wafer and chip probing, optoelectronic testing and magnetic thin-film measurement for MRAM and sensors. Probe systems range from ultra-low-signal I-V/C-V to high-current, high-voltage power devices, RF/sub-THz, magnetic-field-dependent and temperature-controlled testing.", "f": false}, {"t": "Electron Microscopy & High-Resolution Analysis", "u": "metrology-inspection-failure-analysis.html#electron-microscopy-high-resolution-analysis", "d": "Some defects need high-resolution structural or materials analysis. Scanning and transmission electron microscopy (SEM and TEM) provide detailed imagi", "c": "Metrology, Inspection & Failure Analysis", "k": "Some defects need high-resolution structural or materials analysis. Scanning and transmission electron microscopy (SEM and TEM) provide detailed imaging and compositional information. They support process development, contamination analysis, package investigations, materials characterization and root-cause analysis.", "f": false}, {"t": "Laser Sample Preparation for Failure Analysis", "u": "metrology-inspection-failure-analysis.html#laser-sample-preparation-for-failure-analysis", "d": "Targeted sample preparation is often the slowest step in failure analysis. We provide laser-based preparation systems that remove large volumes of mat", "c": "Metrology, Inspection & Failure Analysis", "k": "Targeted sample preparation is often the slowest step in failure analysis. We provide laser-based preparation systems that remove large volumes of material quickly and expose regions of interest in wafers, advanced packages and system-level assemblies.\nApplications include:\nLarge-area package cross-sectionsFlip-chip and solder structuresMEMS cap removal and deep-structure accessTargeted preparation of TSVs, RDLs, interposers, hybrid-bonded stacks and other buried interfaces\nFast bulk removal can cut FIB or PFIB time before precise end-pointing, final polishing and downstream SEM, TEM, X-ray or", "f": false}, {"t": "Manufacturing Data, Yield Analytics & Software", "u": "metrology-inspection-failure-analysis.html#manufacturing-data-yield-analytics-software", "d": "Manufacturing software brings together fabrication, metrology, inspection, assembly and test data. Use it for yield analytics, defect management, SPC,", "c": "Metrology, Inspection & Failure Analysis", "k": "Manufacturing software brings together fabrication, metrology, inspection, assembly and test data. Use it for yield analytics, defect management, SPC, automated reporting, outlier detection, lot disposition, wafer and assembly mapping and equipment monitoring.", "f": false}, {"t": "From Measurement Development to Production", "u": "metrology-inspection-failure-analysis.html#from-measurement-development-to-production", "d": "We can take a measurement or inspection requirement from feasibility testing to a repeatable production workflow. We integrate instruments with handli", "c": "Metrology, Inspection & Failure Analysis", "k": "We can take a measurement or inspection requirement from feasibility testing to a repeatable production workflow. We integrate instruments with handling, robotics, machine vision, fixtures and factory software. Results can feed databases, pass/fail logic and custom reporting or analysis scripts.", "f": false}, {"t": "Equipment Service & Fab Support", "u": "equipment-service-fab-support.html", "d": "Repair, refurbishment and replacement of vacuum pumps, RF generators and matching networks, legacy furnace upgrades, relocation, field service and obsolete spare parts across Asia.", "c": "Industry", "k": "Vacuum Pump Repair, Refurbishment & Replacement RF Generator & Matching Network Support Legacy Furnace & Thermal Equipment Support Equipment Relocation, Installation & Field Service Spare Parts & Obsolescence Support Flexible Support for Mature & Specialty Fabs", "f": false}, {"t": "Vacuum Pump Repair, Refurbishment & Replacement", "u": "equipment-service-fab-support.html#vacuum-pump-repair-refurbishment-replacement", "d": "Vacuum pumps are critical to many deposition, etch, thermal and analytical processes. We support selected vacuum pump models through repair, refurbish", "c": "Equipment Service & Fab Support", "k": "Vacuum pumps are critical to many deposition, etch, thermal and analytical processes. We support selected vacuum pump models through repair, refurbishment, exchange or replacement programs, depending on your installed equipment and needs.\nSupport can include evaluating failed units, coordinating overhaul work, sourcing replacements and handling logistics to your regional sites.", "f": false}, {"t": "RF Generator & Matching Network Support", "u": "equipment-service-fab-support.html#rf-generator-matching-network-support", "d": "RF generators and matching networks are essential subsystems in plasma-based equipment. We support repair, refurbishment and replacement of selected R", "c": "Equipment Service & Fab Support", "k": "RF generators and matching networks are essential subsystems in plasma-based equipment. We support repair, refurbishment and replacement of selected RF power and matching equipment used in etch, deposition and related processes.\nThis gives you another path for aging or hard-to-source subsystems, so you don&#x27;t have to replace an otherwise serviceable process tool.", "f": false}, {"t": "Legacy Furnace & Thermal Equipment Support", "u": "equipment-service-fab-support.html#legacy-furnace-thermal-equipment-support", "d": "Installed diffusion, oxidation and LPCVD furnaces can stay useful for many years when controls, gas systems and key mechanical parts are maintained. W", "c": "Equipment Service & Fab Support", "k": "Installed diffusion, oxidation and LPCVD furnaces can stay useful for many years when controls, gas systems and key mechanical parts are maintained. We support selected legacy thermal equipment with upgrades, refurbishment, spare parts and technical service.\nWhere it makes sense, older systems can be modernized to improve controls, reliability or compatibility with current process requirements.", "f": false}, {"t": "Equipment Relocation, Installation & Field Service", "u": "equipment-service-fab-support.html#equipment-relocation-installation-field-service", "d": "We coordinate de-installation, relocation, re-installation, commissioning and field service for selected equipment. Our regional team supports custome", "c": "Equipment Service & Fab Support", "k": "We coordinate de-installation, relocation, re-installation, commissioning and field service for selected equipment. Our regional team supports customers running several manufacturing sites across Asia. Where needed, we coordinate with equipment manufacturers and specialist service partners.", "f": false}, {"t": "Spare Parts & Obsolescence Support", "u": "equipment-service-fab-support.html#spare-parts-obsolescence-support", "d": "Obsolete components can cause outsized downtime on mature equipment. We help source replacement parts, identify compatible alternatives and coordinate", "c": "Equipment Service & Fab Support", "k": "Obsolete components can cause outsized downtime on mature equipment. We help source replacement parts, identify compatible alternatives and coordinate repair or refurbishment of selected subsystems.\nFor equipment nearing end of support, we help you decide which path is most practical: refurbishment, subsystem replacement or full tool replacement.", "f": false}, {"t": "Flexible Support for Mature & Specialty Fabs", "u": "equipment-service-fab-support.html#flexible-support-for-mature-specialty-fabs", "d": "Not every fab runs only the newest production equipment. Research fabs, MEMS lines, power semiconductor facilities and specialty manufacturers often r", "c": "Equipment Service & Fab Support", "k": "Not every fab runs only the newest production equipment. Research fabs, MEMS lines, power semiconductor facilities and specialty manufacturers often rely on mature tools that are still technically capable but need flexible support. We work with these customers to keep useful equipment running and to find practical upgrade or replacement options.", "f": false}, {"t": "Optics & Photonics", "u": "optics-photonics.html", "d": "Equipment for precision optics, AR/VR waveguides and wafer-level optics, photonic devices, optical interconnects and co-packaged optics: interferometry, alignment, coating, nanoimprint and test.", "c": "Industry", "k": "Precision Optics & Optical Manufacturing AR/VR & Wafer-Level Optics Photonics, Optoelectronics & Optical Interconnects Custom & Emerging Optical Applications", "f": true}, {"t": "Precision Optics & Optical Manufacturing", "u": "optics-photonics.html#precision-optics-optical-manufacturing", "d": "Conventional optical components and assemblies such as lenses, mirrors, windows, filters and coated optics. Capabilities include interferometric and s", "c": "Optics & Photonics", "k": "Conventional optical components and assemblies such as lenses, mirrors, windows, filters and coated optics. Capabilities include interferometric and surface metrology, thin-film characterization, lens alignment, coating deposition and precision glass processing, from fabrication through final optical assembly.", "f": false}, {"t": "AR/VR & Wafer-Level Optics", "u": "optics-photonics.html#ar-vr-wafer-level-optics", "d": "Wafer-scale manufacture of micro- and nanostructured optics, including AR/VR waveguides, diffractive elements, microlens arrays and compact wafer-leve", "c": "Optics & Photonics", "k": "Wafer-scale manufacture of micro- and nanostructured optics, including AR/VR waveguides, diffractive elements, microlens arrays and compact wafer-level optical systems. Technologies include nanoimprint, lens replication and stacking, high-index glass processing, deposition, plasma processing and process metrology.", "f": false}, {"t": "Photonics, Optoelectronics & Optical Interconnects", "u": "optics-photonics.html#photonics-optoelectronics-optical-interconnects", "d": "Active and passive photonic devices and optical communication hardware, including lasers, VCSELs, photodetectors, PICs, optical sensors, optical I/O a", "c": "Optics & Photonics", "k": "Active and passive photonic devices and optical communication hardware, including lasers, VCSELs, photodetectors, PICs, optical sensors, optical I/O and CPO. Capabilities run from device fabrication and wafer-level integration through optical alignment, packaging and electrical/optical test.", "f": false}, {"t": "Custom & Emerging Optical Applications", "u": "optics-photonics.html#custom-emerging-optical-applications", "d": "Some optical designs don&#x27;t have a standard process flow yet. For these, we support feasibility testing, custom fixtures and tooling, precision mo", "c": "Optics & Photonics", "k": "Some optical designs don&#x27;t have a standard process flow yet. For these, we support feasibility testing, custom fixtures and tooling, precision motion and alignment, automated handling, machine vision, metrology integration and production automation.", "f": false}, {"t": "Precision Optics & Optical Manufacturing", "u": "precision-optics-optical-manufacturing.html", "d": "Interferometers, non-contact 3D surface metrology, thin-film measurement, lens centration and active alignment, optical coating systems and laser glass processing for lens, mirror and filter makers.", "c": "Industry", "k": "Optical Metrology Thin-Film & Optical Characterization Surface & Mechanical Characterization Lens Alignment & Optical Assembly Optical Coatings & Thin-Film Deposition Glass & Optical Component Processing From Optical Process Development to Production", "f": false}, {"t": "Optical Metrology", "u": "precision-optics-optical-manufacturing.html#optical-metrology", "d": "We provide interferometric measurement systems for precision optical components and complete optical systems. They measure surface form, radius of cur", "c": "Precision Optics & Optical Manufacturing", "k": "We provide interferometric measurement systems for precision optical components and complete optical systems. They measure surface form, radius of curvature, transmitted wavefront and other parameters that verify optical performance.\nSystems are available for flat, spherical, aspheric and other challenging surfaces, at visible and infrared wavelengths. Vibration-insensitive technology allows accurate measurement directly in manufacturing areas, so parts don&#x27;t need to travel to an isolated metrology lab.\nNon-contact 3D surface metrology adds production measurement for aspheric and freeform", "f": false}, {"t": "Thin-Film & Optical Characterization", "u": "precision-optics-optical-manufacturing.html#thin-film-optical-characterization", "d": "Optical coatings need precise control of film thickness and optical properties. Our thin-film systems use reflectometry, spectrophotometry and ellipso", "c": "Precision Optics & Optical Manufacturing", "k": "Optical coatings need precise control of film thickness and optical properties. Our thin-film systems use reflectometry, spectrophotometry and ellipsometry to measure coating thickness, refractive index, extinction coefficient, reflectance and transmittance.\nThey support anti-reflective coatings, optical filters, mirrors, transparent films and multilayer optical structures.", "f": false}, {"t": "Surface & Mechanical Characterization", "u": "precision-optics-optical-manufacturing.html#surface-mechanical-characterization", "d": "Optical performance can also depend on surface roughness, coating durability and mechanical properties. We provide equipment to measure roughness, top", "c": "Precision Optics & Optical Manufacturing", "k": "Optical performance can also depend on surface roughness, coating durability and mechanical properties. We provide equipment to measure roughness, topography, friction, wear, hardness, adhesion, scratch resistance and coating performance.\nThese measurements support process development and reliability testing for optical glass, coated components and other precision surfaces.", "f": false}, {"t": "Lens Alignment & Optical Assembly", "u": "precision-optics-optical-manufacturing.html#lens-alignment-optical-assembly", "d": "Accurate alignment is critical for multi-element optical systems. Our precision systems measure and align lens centration, tilt, optical axis, radius ", "c": "Precision Optics & Optical Manufacturing", "k": "Accurate alignment is critical for multi-element optical systems. Our precision systems measure and align lens centration, tilt, optical axis, radius of curvature and element position during assembly.\nEach optical surface can be measured during assembly. That lets you position lenses quantitatively before bonding or fixing, instead of relying only on mechanical references or final system tests. Applications include singlets, cemented lenses, air-spaced assemblies and complex multi-element systems.\nActive alignment also supports production inspection of finished lens stacks. It measures beam de", "f": false}, {"t": "Optical Coatings & Thin-Film Deposition", "u": "precision-optics-optical-manufacturing.html#optical-coatings-thin-film-deposition", "d": "We provide vacuum deposition equipment for optical coating research, process development and production. Technologies include sputtering, electron-bea", "c": "Precision Optics & Optical Manufacturing", "k": "We provide vacuum deposition equipment for optical coating research, process development and production. Technologies include sputtering, electron-beam and thermal evaporation and other physical vapor deposition (PVD) processes.\nApplications include anti-reflective and high-reflective coatings, optical filters, mirrors, beam-control coatings and other functional thin films across ultraviolet, visible and infrared wavelengths.\nSpecialized coating approaches also support:\nLow-loss and high laser-damage-threshold opticsInfrared imaging and thermal opticsProtective diamond-like carbon (DLC) coatin", "f": false}, {"t": "Glass & Optical Component Processing", "u": "precision-optics-optical-manufacturing.html#glass-optical-component-processing", "d": "Precision laser micromachining is a flexible, contactless way to process glass, sapphire and other transparent or brittle materials. We support laser ", "c": "Precision Optics & Optical Manufacturing", "k": "Precision laser micromachining is a flexible, contactless way to process glass, sapphire and other transparent or brittle materials. We support laser cutting, structuring, ablation and selective removal of thin films on optical substrates.\nLaser processes produce complex shapes with minimal mechanical load. They can be integrated with automated handling and inspection for production.", "f": false}, {"t": "From Optical Process Development to Production", "u": "precision-optics-optical-manufacturing.html#from-optical-process-development-to-production", "d": "For unusual optical components or new manufacturing processes, we evaluate feasibility first. Then we combine custom fixtures, motion, handling, inspe", "c": "Precision Optics & Optical Manufacturing", "k": "For unusual optical components or new manufacturing processes, we evaluate feasibility first. Then we combine custom fixtures, motion, handling, inspection and automation around the chosen process, from lab development to integrated production cells.", "f": false}, {"t": "AR/VR & Wafer-Level Optics", "u": "ar-vr-wafer-level-optics.html", "d": "Nanoimprint lithography, wafer-level lens molding and stacking, AR waveguide laser singulation, etch, deposition and metrology for AR/VR, diffractive optics and microlens arrays.", "c": "Industry", "k": "Micro- & Nano-Optical Structures Wafer-Level Lens Manufacturing & Assembly AR/VR Waveguide & High-Index Glass Processing Etch, Deposition & Photonic Processing Metrology & Process Control From Process Development to Production", "f": false}, {"t": "Micro- & Nano-Optical Structures", "u": "ar-vr-wafer-level-optics.html#micro-nano-optical-structures", "d": "Nanoimprint lithography is a scalable way to replicate micro- and nanoscale optical structures across wafer-size substrates. We support processes for ", "c": "AR/VR & Wafer-Level Optics", "k": "Nanoimprint lithography is a scalable way to replicate micro- and nanoscale optical structures across wafer-size substrates. We support processes for diffractive optical elements, optical waveguides, gratings, microlenses and other structured optical surfaces.\nTechnologies include master fabrication, UV nanoimprint, hot embossing and transfer of optical structures into production substrates. Nanoimprint also scales to large-area panel substrates for displays and photonic structures such as wire-grid polarizers. Applications go beyond AR/VR into sensing, illumination, imaging and other miniatur", "f": false}, {"t": "Wafer-Level Lens Manufacturing & Assembly", "u": "ar-vr-wafer-level-optics.html#wafer-level-lens-manufacturing-assembly", "d": "Wafer-level manufacturing makes and assembles large numbers of optical elements in parallel. Capabilities include microlens molding, wafer-level repli", "c": "AR/VR & Wafer-Level Optics", "k": "Wafer-level manufacturing makes and assembles large numbers of optical elements in parallel. Capabilities include microlens molding, wafer-level replication, precision alignment, UV bonding and aligned stacking of lens and spacer wafers.\nThese processes support wafer-level cameras, 3D sensing, infrared sensing, compact imaging modules and other systems where size, alignment and throughput are critical.\nHigh-precision die attach and optoelectronic assembly also support AR/VR emitters, image sensors, MEMS devices and other compact optical modules that need micron-level placement and reliable bon", "f": false}, {"t": "AR/VR Waveguide & High-Index Glass Processing", "u": "ar-vr-wafer-level-optics.html#ar-vr-waveguide-high-index-glass-processing", "d": "AR/VR eyepieces and waveguides often use high-index glasses and other transparent crystalline materials that are hard to process mechanically. Precisi", "c": "AR/VR & Wafer-Level Optics", "k": "AR/VR eyepieces and waveguides often use high-index glasses and other transparent crystalline materials that are hard to process mechanically. Precision laser technologies can separate and process these materials at wafer and component level.\nApplications include singulation of AR waveguides and eyepieces, laser cutting, structuring and other processing of transparent substrates with minimal chipping and mechanical damage.", "f": false}, {"t": "Etch, Deposition & Photonic Processing", "u": "ar-vr-wafer-level-optics.html#etch-deposition-photonic-processing", "d": "Micro- and nano-optical devices may need semiconductor-style fabrication alongside conventional optical manufacturing. We provide plasma etching, thin", "c": "AR/VR & Wafer-Level Optics", "k": "Micro- and nano-optical devices may need semiconductor-style fabrication alongside conventional optical manufacturing. We provide plasma etching, thin-film deposition, surface treatment and related equipment for optical and photonic materials.\nThese support waveguides, gratings, microLED structures and other devices that combine optical function with microfabricated features.\nThin-film coating processes also support:\nPrecision waveguide coatingsHard anti-reflective surfacesTransparent conductive layers and electrochromic structuresControlled transmission or color on smart-glass and wearable-di", "f": false}, {"t": "Metrology & Process Control", "u": "ar-vr-wafer-level-optics.html#metrology-process-control", "d": "Measurement is needed throughout wafer-level optical manufacturing to control substrates, films and finished optical performance. We support thin-film", "c": "AR/VR & Wafer-Level Optics", "k": "Measurement is needed throughout wafer-level optical manufacturing to control substrates, films and finished optical performance. We support thin-film thickness and optical-property measurement, surface and topography characterization, and interferometric measurement of optical components and systems.\nHigh-speed non-contact 3D metrology inspects microlens arrays, diffractive features and transparent films. Display-oriented measurements quantify photo-spacer geometry, color-filter structures, local defects and other features that cause optical non-uniformity.\nAutomated inspection and machine vi", "f": false}, {"t": "From Process Development to Production", "u": "ar-vr-wafer-level-optics.html#from-process-development-to-production", "d": "New optical designs may combine imprinting, laser processing, bonding, deposition and metrology with no standard equipment setup. We support feasibili", "c": "AR/VR & Wafer-Level Optics", "k": "New optical designs may combine imprinting, laser processing, bonding, deposition and metrology with no standard equipment setup. We support feasibility trials, custom tooling, handling and inspection, then automate the process as it moves to pilot or volume manufacturing.", "f": false}, {"t": "Photonics, Optoelectronics & Optical Interconnects", "u": "photonics-optoelectronics-optical-interconnects.html", "d": "Photonic device fabrication, wafer-level photonic integration, co-packaged optics and optical I/O, active alignment, photonic metrology and optoelectronic wafer test for lasers, VCSELs and PICs.", "c": "Industry", "k": "Photonic Device Fabrication Wafer-Level Integration & Photonic Packaging Co-Packaged Optics & Optical I/O Photonic Process Metrology Optoelectronic Device Test Manufacturing Data & Yield Analytics Precision Optical Alignment Quantum Photonics & Emerging Integration Fiber Optics & Specialized Photonic Manufacturing From Photonic R&D to Production", "f": false}, {"t": "Photonic Device Fabrication", "u": "photonics-optoelectronics-optical-interconnects.html#photonic-device-fabrication", "d": "Photonic devices are made from many materials, including silicon-based materials, compound semiconductors and optical crystals. We provide plasma etch", "c": "Photonics, Optoelectronics & Optical Interconnects", "k": "Photonic devices are made from many materials, including silicon-based materials, compound semiconductors and optical crystals. We provide plasma etching, deposition, wafer cleaning, surface treatment and precision laser processing for photonic device fabrication.\nProcesses support lasers, waveguides, detectors, microLEDs, gratings and other optical or optoelectronic structures. Laser lift-off also supports microLED and other compound semiconductor devices where functional layers must be separated from growth or carrier substrates.\nPVD thin-film processes support photonic integrated circuits, ", "f": false}, {"t": "Wafer-Level Integration & Photonic Packaging", "u": "photonics-optoelectronics-optical-interconnects.html#wafer-level-integration-photonic-packaging", "d": "Modern photonic systems combine optical, electronic and mechanical structures in tightly integrated packages. We support wafer bonding, thin-wafer pro", "c": "Photonics, Optoelectronics & Optical Interconnects", "k": "Modern photonic systems combine optical, electronic and mechanical structures in tightly integrated packages. We support wafer bonding, thin-wafer processing, lithography, nanoimprint and precision assembly for photonic integration.\nApplications include optical coupling structures, grating couplers, beam-shaping elements, heterogeneous photonic integration and other architectures that combine several materials and device functions.\nPrecision assembly supports commercial laser, infrared, LiDAR, MEMS/CIS and optical-communication modules, using high-accuracy die placement and suitable bonding me", "f": false}, {"t": "Co-Packaged Optics & Optical I/O", "u": "photonics-optoelectronics-optical-interconnects.html#co-packaged-optics-optical-i-o", "d": "AI infrastructure and high-performance computing are pulling optical interconnects closer to electronic processors. We support manufacturing processes", "c": "Photonics, Optoelectronics & Optical Interconnects", "k": "AI infrastructure and high-performance computing are pulling optical interconnects closer to electronic processors. We support manufacturing processes for co-packaged optics and optical I/O, including wafer and die integration, optical coupling structures, precision alignment and photonic packaging.\nAlignment technologies support lenses, fiber arrays and other optical interfaces that need precise positioning between photonic devices and external optical connections.", "f": false}, {"t": "Photonic Process Metrology", "u": "photonics-optoelectronics-optical-interconnects.html#photonic-process-metrology", "d": "Photonic manufacturing often needs dimensional and layer measurements in addition to optical testing. We support non-contact 3D topography, transparen", "c": "Photonics, Optoelectronics & Optical Interconnects", "k": "Photonic manufacturing often needs dimensional and layer measurements in addition to optical testing. We support non-contact 3D topography, transparent-film thickness and multilayer or subsurface metrology for photonic wafers and device structures.\nApplications include patterned photoresist on silicon or compound semiconductor wafers, post-development and pre-etch checks, transparent functional layers and microfabricated features in VCSELs, LEDs, MEMS and other photonic devices.", "f": false}, {"t": "Optoelectronic Device Test", "u": "photonics-optoelectronics-optical-interconnects.html#optoelectronic-device-test", "d": "Optoelectronic devices need both electrical and optical characterization. We provide wafer- and chip-level probe systems for combined measurement of V", "c": "Photonics, Optoelectronics & Optical Interconnects", "k": "Optoelectronic devices need both electrical and optical characterization. We provide wafer- and chip-level probe systems for combined measurement of VCSELs, laser diodes, LEDs, photodiodes and avalanche photodiodes.\nDepending on the device, measurements include:\nElectrical characteristicsEmitted optical power and wavelengthNear- and far-field beam behaviorFrequency response", "f": false}, {"t": "Manufacturing Data & Yield Analytics", "u": "photonics-optoelectronics-optical-interconnects.html#manufacturing-data-yield-analytics", "d": "Manufacturing software brings photonics data together across wafer fabrication, optical/electrical wafer test, assembly, burn-in and final test. Yield", "c": "Photonics, Optoelectronics & Optical Interconnects", "k": "Manufacturing software brings photonics data together across wafer fabrication, optical/electrical wafer test, assembly, burn-in and final test. Yield analytics, automated reporting and custom integrations link wafer-level measurements to assembly conditions and final device performance.", "f": false}, {"t": "Precision Optical Alignment", "u": "photonics-optoelectronics-optical-interconnects.html#precision-optical-alignment", "d": "Photonic modules often need micron or sub-micron alignment of lenses, fibers and optical axes. Passive or active alignment, precision motion, componen", "c": "Photonics, Optoelectronics & Optical Interconnects", "k": "Photonic modules often need micron or sub-micron alignment of lenses, fibers and optical axes. Passive or active alignment, precision motion, component handling and custom fixtures can be integrated with bonding, dispensing, curing and inspection.", "f": false}, {"t": "Quantum Photonics & Emerging Integration", "u": "photonics-optoelectronics-optical-interconnects.html#quantum-photonics-emerging-integration", "d": "Emerging photonic and quantum devices can require low-temperature heterogeneous integration of materials such as silicon, lithium niobate and III-V se", "c": "Photonics, Optoelectronics & Optical Interconnects", "k": "Emerging photonic and quantum devices can require low-temperature heterogeneous integration of materials such as silicon, lithium niobate and III-V semiconductors. These are hard to combine through conventional growth alone.", "f": false}, {"t": "Fiber Optics & Specialized Photonic Manufacturing", "u": "photonics-optoelectronics-optical-interconnects.html#fiber-optics-specialized-photonic-manufacturing", "d": "Specialized photonic manufacturing can also include optical-fiber preform fabrication and related optical-communication processes.", "c": "Photonics, Optoelectronics & Optical Interconnects", "k": "Specialized photonic manufacturing can also include optical-fiber preform fabrication and related optical-communication processes.", "f": false}, {"t": "From Photonic R&D to Production", "u": "photonics-optoelectronics-optical-interconnects.html#from-photonic-r-d-to-production", "d": "For emerging photonic applications where standard equipment is not the full answer, we combine process equipment, alignment, metrology, fixtures, hand", "c": "Photonics, Optoelectronics & Optical Interconnects", "k": "For emerging photonic applications where standard equipment is not the full answer, we combine process equipment, alignment, metrology, fixtures, handling and automation around the workflow you need.", "f": false}, {"t": "Aerospace Manufacturing & MRO", "u": "aerospace.html", "d": "Portable 3D defect inspection for turbine blades, automated dimensional metrology, tribology and coating testing, failure analysis, optical active alignment and custom inspection systems for aerospace.", "c": "Industry", "k": "Portable & In-Situ Defect Inspection Automated 3D Inspection & Dimensional Metrology Materials, Coatings & Tribology Microscopy & Failure Analysis Aerospace & Defense Optical Assembly Automated Inspection & Custom Metrology Systems From Feasibility to Production", "f": false}, {"t": "Portable & In-Situ Defect Inspection", "u": "aerospace.html#portable-in-situ-defect-inspection", "d": "Portable 3D inspection systems let engineers measure defects directly on large or hard-to-move parts. There is no need to send them to a metrology lab", "c": "Aerospace & MRO", "k": "Portable 3D inspection systems let engineers measure defects directly on large or hard-to-move parts. There is no need to send them to a metrology lab. Non-contact systems measure scratches, pits, nicks, dents, corrosion, edge breaks, radii and other surface features.\nTypical applications include turbine blades, engine components, machined parts and hard-to-reach surfaces. Quantitative 3D measurement reduces reliance on visual inspection and manual gauges. Engineers make faster, more consistent repair, rework and acceptance decisions.", "f": false}, {"t": "Automated 3D Inspection & Dimensional Metrology", "u": "aerospace.html#automated-3d-inspection-dimensional-metrology", "d": "We support automated 3D inspection of aerospace components using non-contact optical measurement, machine vision, robotics and precision motion. These", "c": "Aerospace & MRO", "k": "We support automated 3D inspection of aerospace components using non-contact optical measurement, machine vision, robotics and precision motion. These systems check dimensional features, surface geometry and production defects right on the factory floor.\nApplications include complex machined components, composite structures, castings and large assemblies where coordinate measurement or manual inspection is slow or hard to automate.", "f": false}, {"t": "Materials, Coatings & Tribology", "u": "aerospace.html#materials-coatings-tribology", "d": "We provide laboratory equipment for testing aerospace materials, coatings and lubricants. It measures friction, wear, fretting, adhesion, hardness, su", "c": "Aerospace & MRO", "k": "We provide laboratory equipment for testing aerospace materials, coatings and lubricants. It measures friction, wear, fretting, adhesion, hardness, surface roughness and coating performance.\nTests can run under controlled conditions such as high or cryogenic temperature, vacuum, humidity and high mechanical loads. This supports development and qualification of engine components, bearings, gears, actuators, composites, lubricants and aerospace coatings.", "f": false}, {"t": "Microscopy & Failure Analysis", "u": "aerospace.html#microscopy-failure-analysis", "d": "When defects need closer investigation, electron microscopy and related techniques support materials analysis, fracture investigation, contamination a", "c": "Aerospace & MRO", "k": "When defects need closer investigation, electron microscopy and related techniques support materials analysis, fracture investigation, contamination analysis and root-cause studies.\nThese tools complement dimensional and surface inspection with detail on microstructure, interfaces and failure mechanisms.", "f": false}, {"t": "Aerospace & Defense Optical Assembly", "u": "aerospace.html#aerospace-defense-optical-assembly", "d": "Aerospace, space and defense systems can contain large-aperture or deep multi-element optical assemblies. Mechanical references alone often cannot rea", "c": "Aerospace & MRO", "k": "Aerospace, space and defense systems can contain large-aperture or deep multi-element optical assemblies. Mechanical references alone often cannot reach the required optical-axis accuracy. We support non-contact active alignment of lenses and optical surfaces during assembly, including large imaging systems, laser collimators, telescope-related assemblies and other precision optical modules.\nFor infrared and electro-optical systems, we also support specialized thin-film coatings for thermal imaging, night vision and other IR optics, including protective and low-loss coatings for harsh environm", "f": false}, {"t": "Automated Inspection & Custom Metrology Systems", "u": "aerospace.html#automated-inspection-custom-metrology-systems", "d": "We develop semi- or fully automated inspection systems around your component and production process. We integrate metrology equipment with robots, pre", "c": "Aerospace & MRO", "k": "We develop semi- or fully automated inspection systems around your component and production process. We integrate metrology equipment with robots, precision motion, machine vision, part handling and production software.\nCustom fixtures and part-handling systems position components accurately and repeatably during inspection. We can also deliver:\nMechanical design and safety enclosuresControl systems and measurement recipesAutomated data collection and pass/fail reportingConnection to factory databases and existing quality systems", "f": false}, {"t": "From Feasibility to Production", "u": "aerospace.html#from-feasibility-to-production", "d": "When your application needs custom hardware, we support the design and contract manufacturing of fixtures, tooling, mechanical assemblies and other sy", "c": "Aerospace & MRO", "k": "When your application needs custom hardware, we support the design and contract manufacturing of fixtures, tooling, mechanical assemblies and other system components. We manage projects from feasibility testing and measurement development through system design, fabrication, integration, installation and production support.", "f": false}, {"t": "AI Computing & Data Center Hardware", "u": "ai-computing-data-center-hardware.html", "d": "Hybrid bonding for HBM and chiplets, co-packaged optics and optical I/O, advanced package inspection, failure analysis, yield analytics and thermal-management micromachining for AI accelerators.", "c": "Industry", "k": "AI Accelerators, HBM & Advanced Packaging Co-Packaged Optics & High-Speed Optical Interconnects Inspection, Yield & Failure Analysis Manufacturing Data & Yield Analytics Optoelectronic Device Characterization Thermal Management & Emerging Cooling Technologies From Feasibility to Production", "f": false}, {"t": "AI Accelerators, HBM & Advanced Packaging", "u": "ai-computing-data-center-hardware.html#ai-accelerators-hbm-advanced-packaging", "d": "AI processors increasingly rely on high-bandwidth memory, chiplets, advanced substrates and 2.5D/3D integration. We support wafer-to-wafer and die-to-", "c": "AI & Data Center Hardware", "k": "AI processors increasingly rely on high-bandwidth memory, chiplets, advanced substrates and 2.5D/3D integration. We support wafer-to-wafer and die-to-wafer bonding, hybrid bonding, thin-wafer handling, precision die placement and related heterogeneous-integration processes.\nThese technologies are used in HBM stacks, logic-memory integration, chiplet architectures, fan-out packaging and other high-density packages. They increase bandwidth while shortening interconnects and lowering power use.", "f": false}, {"t": "Co-Packaged Optics & High-Speed Optical Interconnects", "u": "ai-computing-data-center-hardware.html#co-packaged-optics-high-speed-optical-interconnects", "d": "Electrical interconnects are becoming a bottleneck, so optical links are moving closer to switches, processors and accelerators. We support silicon ph", "c": "AI & Data Center Hardware", "k": "Electrical interconnects are becoming a bottleneck, so optical links are moving closer to switches, processors and accelerators. We support silicon photonics, optical I/O and co-packaged optics through wafer bonding, nanoimprint, photonic device processing, precision optical alignment and optical/electrical device testing.\nApplications include coupling structures, gratings, lenses, fiber-array alignment, photonic dies and other elements that connect high-speed optical networks directly to advanced electronic packages.", "f": false}, {"t": "Inspection, Yield & Failure Analysis", "u": "ai-computing-data-center-hardware.html#inspection-yield-failure-analysis", "d": "AI hardware combines expensive dies, dense interconnects and multiple stacked layers. Early defect detection and fast failure analysis matter more tha", "c": "AI & Data Center Hardware", "k": "AI hardware combines expensive dies, dense interconnects and multiple stacked layers. Early defect detection and fast failure analysis matter more than ever. We provide automated optical inspection, X-ray and CT, scanning acoustic microscopy, thin-film metrology, electron microscopy and other methods for wafers and advanced packages.\nLaser-based sample preparation speeds up access to regions of interest in complex packages before SEM, FIB or TEM analysis. Emerging workflows target TSVs, redistribution layers, interposers and buried bonding interfaces in 2.5D/3D packages.", "f": false}, {"t": "Manufacturing Data & Yield Analytics", "u": "ai-computing-data-center-hardware.html#manufacturing-data-yield-analytics", "d": "AI accelerators, HBM and photonic modules combine costly dies and process steps, so yield learning and traceability are increasingly important. We pro", "c": "AI & Data Center Hardware", "k": "AI accelerators, HBM and photonic modules combine costly dies and process steps, so yield learning and traceability are increasingly important. We provide software for process and yield analytics, defect management, statistical process control, wafer and assembly mapping, automated reporting and data correlation across fabrication, packaging and test.\nCustom data integrations connect metrology, inspection and test results with your existing manufacturing systems. Engineers can spot process drift, isolate yield loss and find root causes faster.", "f": false}, {"t": "Optoelectronic Device Characterization", "u": "ai-computing-data-center-hardware.html#optoelectronic-device-characterization", "d": "Optical interconnects rely on lasers, VCSELs, photodiodes and other optoelectronic devices that need electrical and optical testing. We support wafer-", "c": "AI & Data Center Hardware", "k": "Optical interconnects rely on lasers, VCSELs, photodiodes and other optoelectronic devices that need electrical and optical testing. We support wafer- and chip-level probing, optical power and wavelength measurement, beam characterization and related evaluation during development and production.", "f": false}, {"t": "Thermal Management & Emerging Cooling Technologies", "u": "ai-computing-data-center-hardware.html#thermal-management-emerging-cooling-technologies", "d": "Rising power density creates new needs for heat spreading, cooling and fluid delivery close to high-performance devices. We support precision micromac", "c": "AI & Data Center Hardware", "k": "Rising power density creates new needs for heat spreading, cooling and fluid delivery close to high-performance devices. We support precision micromachining and custom process development for advanced thermal-management structures.\nEmerging approaches include internal channels, microfluidic structures and other features in glass or related materials. For new applications, we help evaluate feasibility and develop the fixtures, handling and automation.", "f": false}, {"t": "From Feasibility to Production", "u": "ai-computing-data-center-hardware.html#from-feasibility-to-production", "d": "AI hardware architectures change quickly and often need non-standard process combinations. We support feasibility work and integration of process tool", "c": "AI & Data Center Hardware", "k": "AI hardware architectures change quickly and often need non-standard process combinations. We support feasibility work and integration of process tools, metrology, alignment, fixtures and automation as new packaging, photonic and thermal concepts move toward repeatable production.", "f": false}, {"t": "Life Sciences, Diagnostics & Medical Devices", "u": "life-sciences-diagnostics-medical-devices.html", "d": "Electron microscopy for biology, microfluidic and lab-on-chip fabrication, diagnostic substrate inspection, precision glass processing, biomedical thin films and medical-device tribology.", "c": "Industry", "k": "Advanced Microscopy & Biological Imaging Biomedical Optical Metrology & Assembly Genomics & Diagnostic Manufacturing Microfluidics, Biochips & Lab-on-Chip Precision Glass & Internal Channel Structures Biomedical Thin Films & Nanomaterials Biomaterials & Medical-Device Tribology", "f": false}, {"t": "Advanced Microscopy & Biological Imaging", "u": "life-sciences-diagnostics-medical-devices.html#advanced-microscopy-biological-imaging", "d": "We provide scanning and transmission electron microscopy solutions for high-resolution imaging of biological samples. Applications range from surface ", "c": "Life Sciences & Medical Devices", "k": "We provide scanning and transmission electron microscopy solutions for high-resolution imaging of biological samples. Applications range from surface morphology and cellular ultrastructure to tissue imaging, volume electron microscopy, tomography and structural biology.\nElectron microscopy complements optical and fluorescence methods by revealing structures at nanometer resolution. It supports research in cell biology, microbiology, neuroscience, pathology, biomaterials and related fields.", "f": false}, {"t": "Biomedical Optical Metrology & Assembly", "u": "life-sciences-diagnostics-medical-devices.html#biomedical-optical-metrology-assembly", "d": "Optical metrology supports biomedical and ophthalmic applications that need fast, non-contact measurement. Examples include contact lenses and lens mo", "c": "Life Sciences & Medical Devices", "k": "Optical metrology supports biomedical and ophthalmic applications that need fast, non-contact measurement. Examples include contact lenses and lens molds, and research measurements of the corneal surface and tear-film thickness, where subject motion can limit conventional interferometry.\nPrecision active alignment also supports medical optical assemblies such as endoscopes and microscope objectives. In these, the centering and tilt of each lens element directly affect image quality and repeatability.", "f": false}, {"t": "Genomics & Diagnostic Manufacturing", "u": "life-sciences-diagnostics-medical-devices.html#genomics-diagnostic-manufacturing", "d": "Diagnostic and sequencing consumables often contain dense arrays of small features that need consistent manufacturing quality. We provide automated op", "c": "Life Sciences & Medical Devices", "k": "Diagnostic and sequencing consumables often contain dense arrays of small features that need consistent manufacturing quality. We provide automated optical inspection and defect-analysis technologies for precision substrates, patterned surfaces and other diagnostic components.\nAI-assisted inspection helps manufacturers find particles, surface defects, process variation and other anomalies with less manual review.", "f": false}, {"t": "Microfluidics, Biochips & Lab-on-Chip", "u": "life-sciences-diagnostics-medical-devices.html#microfluidics-biochips-lab-on-chip", "d": "Microfluidic and lab-on-chip devices put channels, chambers, sensors and functional surfaces into compact substrates. We support wafer bonding, nanoim", "c": "Life Sciences & Medical Devices", "k": "Microfluidic and lab-on-chip devices put channels, chambers, sensors and functional surfaces into compact substrates. We support wafer bonding, nanoimprint, hot embossing, lithography, surface processing and other fabrication methods for microfluidic devices.\nApplications include:\nBlood and DNA analysisBiosensors and cell sortingOrgan-on-chip platformsDrug-delivery research\nNon-contact surface and volumetric metrology measures microfluidic cells, transparent layers and internal interfaces without touching delicate structures. Surface topography, layer thickness and subsurface geometry can be c", "f": false}, {"t": "Precision Glass & Internal Channel Structures", "u": "life-sciences-diagnostics-medical-devices.html#precision-glass-internal-channel-structures", "d": "Glass is widely used in diagnostics, microfluidics and optical-biological devices thanks to its chemical stability, optical properties and compatibili", "c": "Life Sciences & Medical Devices", "k": "Glass is widely used in diagnostics, microfluidics and optical-biological devices thanks to its chemical stability, optical properties and compatibility with microfabrication. We support precision laser cutting, micro-drilling and structuring of glass for diagnostic slides, biochips and specialized devices. This includes through-holes and fluidic access features, where conventional machining can cause chipping, cracking or excess stress.\nFor emerging applications, internal channel structures inside glass can also be explored for fluid handling, thermal control and other functions that are hard", "f": false}, {"t": "Biomedical Thin Films & Nanomaterials", "u": "life-sciences-diagnostics-medical-devices.html#biomedical-thin-films-nanomaterials", "d": "Thin-film metrology measures local coating thickness and optical properties on small or patterned biomedical parts. Applications include parylene coat", "c": "Life Sciences & Medical Devices", "k": "Thin-film metrology measures local coating thickness and optical properties on small or patterned biomedical parts. Applications include parylene coatings, polymer films and balloon walls or other thin transparent structures that need microscale measurement spots.\nFor research, vacuum-deposited nanoparticle layers support studies in drug delivery, antimicrobial and antiviral surfaces, biofilms, biosensors and other nanomedicine or diagnostic concepts. We support flexible R&amp;D deposition systems for researchers developing these materials.", "f": false}, {"t": "Biomaterials & Medical-Device Tribology", "u": "life-sciences-diagnostics-medical-devices.html#biomaterials-medical-device-tribology", "d": "We support characterization of medical-device materials, coatings and interfaces through surface metrology, friction and wear testing, scratch and adh", "c": "Life Sciences & Medical Devices", "k": "We support characterization of medical-device materials, coatings and interfaces through surface metrology, friction and wear testing, scratch and adhesion measurement and other mechanical tests.\nApplications include implants, catheters, coatings, polymers and other parts where surface behavior and durability affect performance. For catheters and other minimally invasive devices, testing quantifies lubricity and insertion, push, navigation and removal forces, and links them to changes in surface condition. Custom fixtures, inspection and automation support scale-up where standard equipment doe", "f": false}, {"t": "Automotive & E-Mobility", "u": "automotive-e-mobility.html", "d": "Automated 3D inspection, tribology, EV battery X-ray/CT, SiC/GaN power semiconductor processing, MEMS sensors, LiDAR and camera optics alignment, EMC and failure analysis for automotive.", "c": "Industry", "k": "Vehicle & Component Inspection Materials, Coatings & Tribology EV Batteries & Electronic Assemblies Power Semiconductors Sensors & MEMS LiDAR, Cameras & Optical Sensors EMC, Reliability & Failure Analysis From Feasibility to Production", "f": false}, {"t": "Vehicle & Component Inspection", "u": "automotive-e-mobility.html#vehicle-component-inspection", "d": "Automated, non-contact inspection combines optical 3D measurement, machine vision and robotics. It handles dimensional control and defect detection on", "c": "Automotive & E-Mobility", "k": "Automated, non-contact inspection combines optical 3D measurement, machine vision and robotics. It handles dimensional control and defect detection on trim, castings, machined or molded parts and other vehicle components.\nPortable or automated surface metrology measures paint and coating texture, scratches, pits, edge features and roughness directly on parts or body surfaces. This links surface preparation with final appearance and component quality.", "f": false}, {"t": "Materials, Coatings & Tribology", "u": "automotive-e-mobility.html#materials-coatings-tribology", "d": "Friction, wear, coatings and surface condition directly affect efficiency, noise, durability and reliability. We provide tribology and surface-charact", "c": "Automotive & E-Mobility", "k": "Friction, wear, coatings and surface condition directly affect efficiency, noise, durability and reliability. We provide tribology and surface-characterization equipment for bearings, gears, brakes, lubricants, coatings, electrical contacts and e-drive systems.\nMeasurements include friction, wear, fretting, adhesion, hardness, roughness, film thickness and coating durability under controlled temperature, load and environment. Typical uses:\nBrake-material screeningLubrication and wear in electrified drivetrainsConnector fretting with live electrical-contact monitoringScratch and mar resistance ", "f": false}, {"t": "EV Batteries & Electronic Assemblies", "u": "automotive-e-mobility.html#ev-batteries-electronic-assemblies", "d": "Electric vehicles add inspection needs for batteries, power modules and high-density electronic assemblies. We support 2D X-ray, 3D CT and automated X", "c": "Automotive & E-Mobility", "k": "Electric vehicles add inspection needs for batteries, power modules and high-density electronic assemblies. We support 2D X-ray, 3D CT and automated X-ray inspection for battery structures, solder joints, die-cast components and electronic modules.\nOptical or automated inspection can be added where surface or dimensional quality must be checked alongside internal features.", "f": false}, {"t": "Power Semiconductors", "u": "automotive-e-mobility.html#power-semiconductors", "d": "SiC and GaN devices are increasingly important in traction inverters, charging systems and other high-voltage vehicle electronics. We provide wafer pr", "c": "Automotive & E-Mobility", "k": "SiC and GaN devices are increasingly important in traction inverters, charging systems and other high-voltage vehicle electronics. We provide wafer processing, laser annealing, inspection and failure-analysis technologies for developing and manufacturing wide-bandgap power devices.\nCapabilities include thermal and plasma processing, selective laser annealing, laser trimming, wafer separation and dicing, thin-film metrology, wafer inspection and package analysis.\nWafer-level electrical characterization supports high-current, high-voltage testing of SiC and GaN power devices across controlled te", "f": false}, {"t": "Sensors & MEMS", "u": "automotive-e-mobility.html#sensors-mems", "d": "Vehicles rely on MEMS and magnetic sensors for motion, pressure, steering, throttle, safety and driver-assistance functions. We support wafer bonding,", "c": "Automotive & E-Mobility", "k": "Vehicles rely on MEMS and magnetic sensors for motion, pressure, steering, throttle, safety and driver-assistance functions. We support wafer bonding, microfabrication, magnetic-sensor processing, inspection and characterization for these devices.\nFor MEMS that need controlled cavity conditions, aligned wafer bonding provides hermetic or high-vacuum encapsulation for inertial sensors, microbolometers and other sensing devices used in automotive and autonomous systems.\nPrecision optical and photonic technologies also support sensing and imaging applications that need optical components or align", "f": false}, {"t": "LiDAR, Cameras & Optical Sensors", "u": "automotive-e-mobility.html#lidar-cameras-optical-sensors", "d": "Driver-assistance and autonomous systems depend on LiDAR, cameras, infrared imaging and other optical sensors. We support precision die attach and opt", "c": "Automotive & E-Mobility", "k": "Driver-assistance and autonomous systems depend on LiDAR, cameras, infrared imaging and other optical sensors. We support precision die attach and optoelectronic packaging for emitters, receivers, CMOS image sensors and IR modules. We also support active alignment of lenses, camera objectives, detector planes, apertures and reticles where optical-axis accuracy affects performance.\nSpecialized coatings support:\nHigh-performance LiDAR opticsDriver-monitoring and front/rear camera opticsNight-vision systems, rain and ambient-light sensorsProtective sensor covers and smart or electrochromic vehicl", "f": false}, {"t": "EMC, Reliability & Failure Analysis", "u": "automotive-e-mobility.html#emc-reliability-failure-analysis", "d": "As vehicles carry more high-speed electronics and power conversion, electromagnetic compatibility (EMC) and reliability matter more. We support PCB- a", "c": "Automotive & E-Mobility", "k": "As vehicles carry more high-speed electronics and power conversion, electromagnetic compatibility (EMC) and reliability matter more. We support PCB- and IC-level EMC development, X-ray and acoustic inspection, electron microscopy and other failure-analysis techniques for automotive electronics. High-resolution analysis also supports investigation of power-semiconductor metallization and interconnects after electrical and thermal stress testing.", "f": false}, {"t": "From Feasibility to Production", "u": "automotive-e-mobility.html#from-feasibility-to-production", "d": "We integrate robotics, machine vision, metrology, handling, fixtures and production software around non-standard components or processes. Optional add", "c": "Automotive & E-Mobility", "k": "We integrate robotics, machine vision, metrology, handling, fixtures and production software around non-standard components or processes. Optional additions include optimization, dashboards, reporting and inspection/test-data integration.", "f": false}, {"t": "Data Storage & Magnetic Devices", "u": "data-storage-magnetic-devices.html", "d": "Magnetic thin-film wafer mapping, disk media DLC metrology, head and slider measurement, MRAM characterization, GMR/TMR sensor laser annealing and tribology for data storage and spintronics.", "c": "Industry", "k": "Magnetic Thin-Film & Wafer Metrology Disk Media Thin-Film Metrology Heads, Sliders & Precision Components MRAM & Emerging Magnetic Memory GMR/TMR Sensors & Magnetic Device Processing Surface, Tribology & Failure Analysis From Materials Development to Production", "f": false}, {"t": "Magnetic Thin-Film & Wafer Metrology", "u": "data-storage-magnetic-devices.html#magnetic-thin-film-wafer-metrology", "d": "We provide non-contact magnetic measurement systems for magnetic multilayer wafers and thin films. Full-wafer mapping measures the magnetic properties", "c": "Data Storage & Magnetic Devices", "k": "We provide non-contact magnetic measurement systems for magnetic multilayer wafers and thin films. Full-wafer mapping measures the magnetic properties used in development and production of data-storage, MRAM and magnetic-sensor devices.\nThin-film hysteresis and magnetoresistance measurement supports research and quality control of soft and hard magnetic materials on wafers and other samples.\nElectrical probing under an applied magnetic field adds device-level characterization of magnetic sensors, MRAM structures and other magnetically responsive devices. It links film-level magnetic properties", "f": false}, {"t": "Disk Media Thin-Film Metrology", "u": "data-storage-magnetic-devices.html#disk-media-thin-film-metrology", "d": "Hard-disk media need precise control of ultra-thin protective and magnetic layers. We provide optical metrology that measures diamond-like carbon (DLC", "c": "Data Storage & Magnetic Devices", "k": "Hard-disk media need precise control of ultra-thin protective and magnetic layers. We provide optical metrology that measures diamond-like carbon (DLC) thickness, optical properties and magnetic-layer thickness on disk media.\nThese measurements support process development, uniformity control and production quality assurance for advanced media.\nMicroscale optical film measurement adds local thickness and optical-property mapping on small, patterned or non-standard regions where large-spot measurement is not enough.", "f": false}, {"t": "Heads, Sliders & Precision Components", "u": "data-storage-magnetic-devices.html#heads-sliders-precision-components", "d": "Data-storage heads and sliders need tight dimensional, surface and thin-film control. We support optical and surface metrology, thin-film characteriza", "c": "Data Storage & Magnetic Devices", "k": "Data-storage heads and sliders need tight dimensional, surface and thin-film control. We support optical and surface metrology, thin-film characterization, microscopy and other measurement methods used during head and slider processing.\nWhere special handling or automation is needed, measurement equipment can be integrated with custom fixtures and motion systems.", "f": false}, {"t": "MRAM & Emerging Magnetic Memory", "u": "data-storage-magnetic-devices.html#mram-emerging-magnetic-memory", "d": "MRAM manufacturing needs control of very thin magnetic multilayers, annealing and magnetic orientation across the wafer. We support magnetic wafer map", "c": "Data Storage & Magnetic Devices", "k": "MRAM manufacturing needs control of very thin magnetic multilayers, annealing and magnetic orientation across the wafer. We support magnetic wafer mapping, electrical characterization, thin-film metrology and related measurement for MRAM development and production.\nThis extends our data-storage portfolio beyond disk media into semiconductor-based non-volatile memory.", "f": false}, {"t": "GMR/TMR Sensors & Magnetic Device Processing", "u": "data-storage-magnetic-devices.html#gmr-tmr-sensors-magnetic-device-processing", "d": "Giant- and tunneling-magnetoresistance (GMR/TMR) devices are increasingly used in automotive, industrial and consumer sensors. We support selective la", "c": "Data Storage & Magnetic Devices", "k": "Giant- and tunneling-magnetoresistance (GMR/TMR) devices are increasingly used in automotive, industrial and consumer sensors. We support selective laser annealing to set magnetic reference directions on integrated GMR/TMR sensors, together with magnetic and thin-film metrology for process control.\nThe same magnetic-device expertise now serves new markets beyond traditional storage.", "f": false}, {"t": "Surface, Tribology & Failure Analysis", "u": "data-storage-magnetic-devices.html#surface-tribology-failure-analysis", "d": "Head-media interaction and precision mechanical parts may need analysis of roughness, friction, wear and coating durability. We provide surface metrol", "c": "Data Storage & Magnetic Devices", "k": "Head-media interaction and precision mechanical parts may need analysis of roughness, friction, wear and coating durability. We provide surface metrology, tribology and high-resolution microscopy to investigate performance and failure mechanisms.\nFor research and production, these technologies can be combined with custom handling or automation for specialized samples.", "f": false}, {"t": "From Materials Development to Production", "u": "data-storage-magnetic-devices.html#from-materials-development-to-production", "d": "We combine magnetic and thin-film metrology, precision processing, surface characterization, failure analysis and custom handling around specialized s", "c": "Data Storage & Magnetic Devices", "k": "We combine magnetic and thin-film metrology, precision processing, surface characterization, failure analysis and custom handling around specialized storage or spintronic devices, from materials development through production quality control.", "f": false}, {"t": "Electronics Assembly, Test & Reliability", "u": "electronics-assembly-test-reliability.html", "d": "SMT and PCB inspection, X-ray and CT for electronics, laser microvia drilling, EMC pre-compliance, RF and sub-THz probing, package failure analysis and production data reporting.", "c": "Industry", "k": "SMT, PCB & Module Inspection PCB & High-Density Interconnect Processing X-Ray & CT for Electronics EMC Development & Pre-Compliance RF, Wireless & High-Frequency Electronics Package & Assembly Failure Analysis Production Data & Reporting Materials, Coatings & Reliability", "f": false}, {"t": "SMT, PCB & Module Inspection", "u": "electronics-assembly-test-reliability.html#smt-pcb-module-inspection", "d": "We provide inspection technologies for solder joints, component placement, connectors, packages and other features on PCBs and electronic modules. Aut", "c": "Electronics Assembly & Test", "k": "We provide inspection technologies for solder joints, component placement, connectors, packages and other features on PCBs and electronic modules. Automated optical inspection and machine vision find visible defects and process variation. X-ray inspection reaches hidden interconnects and internal structures.\nNon-contact 3D metrology adds dimensional control of PCB substrates and fine features:\nLine width and spacingBoard or substrate warpageVia size, depth and position\nThis is useful during process development and incoming quality control, before assembly.", "f": false}, {"t": "PCB & High-Density Interconnect Processing", "u": "electronics-assembly-test-reliability.html#pcb-high-density-interconnect-processing", "d": "As assemblies move to finer pitch and higher density, smaller vias and thinner multilayer structures get harder to process consistently. We support pr", "c": "Electronics Assembly & Test", "k": "As assemblies move to finer pitch and higher density, smaller vias and thinner multilayer structures get harder to process consistently. We support precision laser drilling and ablation for microvias and other fine PCB or interconnect features, where feature size, geometry or material mix challenge conventional methods.\nFor emerging applications, process development can add real-time monitoring and endpoint control. This improves repeatability and lowers the risk of drilling through or damaging underlying layers.", "f": false}, {"t": "X-Ray & CT for Electronics", "u": "electronics-assembly-test-reliability.html#x-ray-ct-for-electronics", "d": "2D X-ray, 3D CT and automated inline X-ray reveal defects you can&#x27;t see from the surface. These include solder voids, bridging, insufficient sold", "c": "Electronics Assembly & Test", "k": "2D X-ray, 3D CT and automated inline X-ray reveal defects you can&#x27;t see from the surface. These include solder voids, bridging, insufficient solder, hidden joints, package defects and internal assembly problems.\nThese systems support process development, production quality control, incoming inspection and lab failure analysis across SMT, power electronics, automotive electronics and other assemblies.", "f": false}, {"t": "EMC Development & Pre-Compliance", "u": "electronics-assembly-test-reliability.html#emc-development-pre-compliance", "d": "Electromagnetic compatibility problems can start at IC, PCB or system level. We provide tools for emissions and immunity investigation, near-field sca", "c": "Electronics Assembly & Test", "k": "Electromagnetic compatibility problems can start at IC, PCB or system level. We provide tools for emissions and immunity investigation, near-field scanning, ESD-related analysis and IC-level EMC testing.\nThey help engineers locate interference sources, understand coupling paths and improve designs before formal compliance testing.", "f": false}, {"t": "RF, Wireless & High-Frequency Electronics", "u": "electronics-assembly-test-reliability.html#rf-wireless-high-frequency-electronics", "d": "RF and wireless electronics need specialized materials, packaging and test methods at frequencies where conventional electrical approaches get difficu", "c": "Electronics Assembly & Test", "k": "RF and wireless electronics need specialized materials, packaging and test methods at frequencies where conventional electrical approaches get difficult. We support thin-film deposition for piezoelectric MEMS, BAW/FBAR and other RF devices, plus high-precision assembly of RF, microwave and hybrid-device packages.\nOn-wafer probing supports RF and sub-THz characterization alongside DC, pulsed and temperature-dependent measurements. Developers can evaluate high-frequency performance before final assembly.", "f": false}, {"t": "Package & Assembly Failure Analysis", "u": "electronics-assembly-test-reliability.html#package-assembly-failure-analysis", "d": "When failures start inside packages or assemblies, non-destructive acoustic inspection, X-ray and high-resolution microscopy help identify delaminatio", "c": "Electronics Assembly & Test", "k": "When failures start inside packages or assemblies, non-destructive acoustic inspection, X-ray and high-resolution microscopy help identify delamination, voids, cracks, die-attach issues, solder defects and other hidden problems.\nElectron microscopy adds structural and materials detail for root-cause analysis. Laser-based sample preparation removes bulk material and exposes targeted regions in packages or system-level boards before microscopy or ion-beam analysis. Typical targets are large-area package cross-sections, flip-chip assemblies and solder joints or balls that are hard to prepare mech", "f": false}, {"t": "Production Data & Reporting", "u": "electronics-assembly-test-reliability.html#production-data-reporting", "d": "Inspection and test equipment generates large volumes of quality data across boards, modules and finished systems. We support automated collection, co", "c": "Electronics Assembly & Test", "k": "Inspection and test equipment generates large volumes of quality data across boards, modules and finished systems. We support automated collection, correlation and reporting of inspection and test results to improve traceability and reduce manual engineering work.\nCustom scripts and software integrations process instrument data, generate reports and connect results to production databases, quality systems or other manufacturing software.", "f": false}, {"t": "Materials, Coatings & Reliability", "u": "electronics-assembly-test-reliability.html#materials-coatings-reliability", "d": "Electronic products may also need characterization of coatings, adhesives, contact surfaces and mechanical interfaces. We support surface roughness, f", "c": "Electronics Assembly & Test", "k": "Electronic products may also need characterization of coatings, adhesives, contact surfaces and mechanical interfaces. We support surface roughness, friction, wear, hardness, adhesion and other materials measurements during product development and reliability evaluation.\nElectrical-connector testing can link fretting wear and corrosion to real-time current, voltage and contact behavior under controlled environments. For specialized production, inspection can also be integrated with handling, machine vision and factory software.", "f": false}, {"t": "Displays & Advanced Optoelectronics", "u": "displays-advanced-optoelectronics.html", "d": "MicroLED and miniLED laser lift-off, transfer and repair, large-area nanoimprint, panel and color-filter metrology, optoelectronic assembly, smart-glass coatings and display test.", "c": "Industry", "k": "MicroLED, MiniLED & Advanced Emitters Large-Area Patterning & Panel Processes Panel, Film & Microstructure Metrology Optoelectronic Assembly & Sensor Packaging Smart Glass, Functional Coatings & Optical Surfaces Electrical, Optical & Reliability Test From Process Development to Production", "f": false}, {"t": "MicroLED, MiniLED & Advanced Emitters", "u": "displays-advanced-optoelectronics.html#microled-miniled-advanced-emitters", "d": "We support laser lift-off, transfer and local repair or rework of microLED, miniLED and related emitters. Precision positioning and automated handling", "c": "Displays & Optoelectronics", "k": "We support laser lift-off, transfer and local repair or rework of microLED, miniLED and related emitters. Precision positioning and automated handling let you transfer or repair individual dies or selected regions without replacing a whole panel or substrate.\nPlasma processing, thin-film deposition and wafer-level optoelectronic testing support upstream LED and microLED device fabrication. High-precision die bonding supports assembly of emitters and other optoelectronic components into modules.", "f": false}, {"t": "Large-Area Patterning & Panel Processes", "u": "displays-advanced-optoelectronics.html#large-area-patterning-panel-processes", "d": "Large-area nanoimprint lithography replicates micro- and nanoscale structures across panel-size substrates for displays, wire-grid polarizers and othe", "c": "Displays & Optoelectronics", "k": "Large-area nanoimprint lithography replicates micro- and nanoscale structures across panel-size substrates for displays, wire-grid polarizers and other optical functions. The same process family supports structured surfaces in photonic and advanced display applications where optical lithography becomes inefficient over large areas.\nLaser processing and custom automation also support selective structuring, trimming and other panel-level processes that need precise, non-contact modification.", "f": false}, {"t": "Panel, Film & Microstructure Metrology", "u": "displays-advanced-optoelectronics.html#panel-film-microstructure-metrology", "d": "Display manufacturing needs measurement of transparent films, color-filter structures, photo spacers, cell gaps, retardation, local topography and oth", "c": "Displays & Optoelectronics", "k": "Display manufacturing needs measurement of transparent films, color-filter structures, photo spacers, cell gaps, retardation, local topography and other features that directly affect optical uniformity. We provide spectroscopic, interferometric and non-contact 3D metrology for these parameters, on research samples and production-scale panels.\nMeasurements cover color-filter spectral properties, multilayer film thickness, refractive index, surface roughness, panel-glass features, microlens arrays and MEMS or micromirror structures. Small-spot and automated mapping systems help where measurement", "f": false}, {"t": "Optoelectronic Assembly & Sensor Packaging", "u": "displays-advanced-optoelectronics.html#optoelectronic-assembly-sensor-packaging", "d": "Advanced displays and related modules can integrate emitters, detectors, image sensors, MEMS, laser sources and optics. We support high-precision die ", "c": "Displays & Optoelectronics", "k": "Advanced displays and related modules can integrate emitters, detectors, image sensors, MEMS, laser sources and optics. We support high-precision die attach, flip-chip/eutectic assembly and related packaging for AR/VR modules, infrared devices, commercial lasers, CMOS image sensors and MEMS products.\nWhere optical coupling is needed, precision motion and alignment can be integrated with bonding, dispensing, curing and inspection for repeatable production. Active lens alignment also supports AR/VR optical modules, compact imaging assemblies and other sensor products that need accurate centering", "f": false}, {"t": "Smart Glass, Functional Coatings & Optical Surfaces", "u": "displays-advanced-optoelectronics.html#smart-glass-functional-coatings-optical-surfaces", "d": "We support PVD and other thin-film coating processes for display glass and smart surfaces, including:\nHard anti-reflective coatingsTransparent conduct", "c": "Displays & Optoelectronics", "k": "We support PVD and other thin-film coating processes for display glass and smart surfaces, including:\nHard anti-reflective coatingsTransparent conductive oxidesElectrochromic layers and controlled transmission or colorAnti-fingerprint and other functional optical coatings\nLarge-area deposition platforms handle sheet and panel substrates. Precision optical coating processes apply to waveguides, sensor optics and other high-performance optical parts used alongside advanced displays.", "f": false}, {"t": "Electrical, Optical & Reliability Test", "u": "displays-advanced-optoelectronics.html#electrical-optical-reliability-test", "d": "Probe systems support flat-panel displays and optoelectronic devices with electrical, optical and temperature-dependent measurements. Applications inc", "c": "Displays & Optoelectronics", "k": "Probe systems support flat-panel displays and optoelectronic devices with electrical, optical and temperature-dependent measurements. Applications include sheet resistance, I-V and C-V characterization, RF or high-speed measurement and combined optical/electrical testing of LEDs, VCSELs, photodiodes and related devices.\nInspection, X-ray, microscopy and other analytical methods add failure analysis when defects start in packaging, interconnects or device structures rather than the visible panel surface.", "f": false}, {"t": "From Process Development to Production", "u": "displays-advanced-optoelectronics.html#from-process-development-to-production", "d": "New display architectures often combine processes that no single standard tool offers. We integrate motion, machine vision, handling, metrology, repai", "c": "Displays & Optoelectronics", "k": "New display architectures often combine processes that no single standard tool offers. We integrate motion, machine vision, handling, metrology, repair, process equipment and software around your application, from R&amp;D feasibility through pilot and volume automation.", "f": false}, {"t": "Photovoltaics & Solar Manufacturing", "u": "photovoltaics-solar-manufacturing.html", "d": "Diffusion furnaces, PVD and plasma deposition, laser contact opening, thermal laser separation for half-cells, roll-to-roll thin-film scribing, thin-film metrology and tandem solar research tools.", "c": "Industry", "k": "Thermal Processing, Diffusion & Deposition Laser Processing of Solar Cells Flexible & Thin-Film Photovoltaics Thin-Film & Optical Metrology Advanced & Multi-Junction Solar Research From Process Development to Production", "f": false}, {"t": "Thermal Processing, Diffusion & Deposition", "u": "photovoltaics-solar-manufacturing.html#thermal-processing-diffusion-deposition", "d": "We provide furnace and thermal-process equipment for diffusion, oxidation, LPCVD and other high-temperature steps in photovoltaic and semiconductor pr", "c": "Photovoltaics & Solar", "k": "We provide furnace and thermal-process equipment for diffusion, oxidation, LPCVD and other high-temperature steps in photovoltaic and semiconductor processing. Systems support R&amp;D, pilot production and selected high-volume applications.\nPlasma and vacuum deposition technologies support passivation, functional films and other materials needed in solar-cell structures.\nPVD platforms also support solar-absorber and functional thin-film development, with flexible sputtering or evaporation setups for research and scalable production.", "f": false}, {"t": "Laser Processing of Solar Cells", "u": "photovoltaics-solar-manufacturing.html#laser-processing-of-solar-cells", "d": "Laser processing gives high precision without mechanical contact and is widely used in modern PV manufacturing. We support laser contact opening, cell", "c": "Photovoltaics & Solar", "k": "Laser processing gives high precision without mechanical contact and is widely used in modern PV manufacturing. We support laser contact opening, cell separation, scribing, structuring and other micromachining for crystalline and thin-film solar technologies.\nThermal laser separation divides full silicon cells into half-cells or other formats while minimizing edge damage and keeping mechanical strength.", "f": false}, {"t": "Flexible & Thin-Film Photovoltaics", "u": "photovoltaics-solar-manufacturing.html#flexible-thin-film-photovoltaics", "d": "Flexible PV materials may need high-speed roll-to-roll patterning of several functional layers. We support laser scribing and isolation for thin-film ", "c": "Photovoltaics & Solar", "k": "Flexible PV materials may need high-speed roll-to-roll patterning of several functional layers. We support laser scribing and isolation for thin-film technologies on flexible substrates, including custom roll-to-roll setups.\nApplications span CIGS, perovskite and other emerging thin-film technologies that need precise, non-contact patterning.", "f": false}, {"t": "Thin-Film & Optical Metrology", "u": "photovoltaics-solar-manufacturing.html#thin-film-optical-metrology", "d": "Solar-cell performance depends on the thickness and optical properties of many deposited layers. We provide reflectometry, spectrophotometry, ellipsom", "c": "Photovoltaics & Solar", "k": "Solar-cell performance depends on the thickness and optical properties of many deposited layers. We provide reflectometry, spectrophotometry, ellipsometry and other optical thin-film measurement for film thickness, refractive index, extinction coefficient, reflectance and transmittance.\nThese measurements support process development, uniformity mapping and production control for coatings, passivation layers, transparent conductive films and other solar-cell materials.\nElectrical characterization complements optical metrology. Four-point-probe measurement gives sheet resistance and related prop", "f": false}, {"t": "Advanced & Multi-Junction Solar Research", "u": "photovoltaics-solar-manufacturing.html#advanced-multi-junction-solar-research", "d": "Next-generation solar cells increasingly combine dissimilar semiconductors, engineered substrates and complex layer stacks. Wafer bonding and heteroge", "c": "Photovoltaics & Solar", "k": "Next-generation solar cells increasingly combine dissimilar semiconductors, engineered substrates and complex layer stacks. Wafer bonding and heterogeneous integration support research into tandem and multi-junction devices where growing all materials in one structure is difficult. This includes low-temperature integration of III-V layers with silicon and other substrates.\nWe work with research institutes and manufacturers to evaluate specialized bonding, deposition, laser-processing and metrology needs for emerging PV architectures.\nNanoparticle deposition also supports exploratory work in li", "f": false}, {"t": "From Process Development to Production", "u": "photovoltaics-solar-manufacturing.html#from-process-development-to-production", "d": "For production, laser processing, inspection and metrology can be integrated with automated handling, recipe control, data collection and factory inte", "c": "Photovoltaics & Solar", "k": "For production, laser processing, inspection and metrology can be integrated with automated handling, recipe control, data collection and factory interfaces. We support feasibility trials, custom fixtures and process development for non-standard formats or emerging materials before scale-up.", "f": false}, {"t": "Industrial & Precision Manufacturing", "u": "industrial-precision-manufacturing.html", "d": "Automated 3D inspection beyond CMM, portable surface gauges, machine vision AOI, tribology and coating testing, laser micro-drilling, large-part metrology and manufacturing analytics software.", "c": "Industry", "k": "Automated 3D Inspection & Dimensional Metrology Machine Vision & Automated Defect Inspection Materials, Coatings & Tribology Precision Laser Processing Large & Complex Components Data Analytics, Optimization & Custom Software From Feasibility to Production", "f": false}, {"t": "Automated 3D Inspection & Dimensional Metrology", "u": "industrial-precision-manufacturing.html#automated-3d-inspection-dimensional-metrology", "d": "We provide non-contact 3D inspection for automated dimensional measurement and surface checks on the production floor. Systems combine precision optic", "c": "Industrial & Precision Manufacturing", "k": "We provide non-contact 3D inspection for automated dimensional measurement and surface checks on the production floor. Systems combine precision optics, machine vision, robotics and computational analysis to measure complex parts without targets or manual probing.\nApplications include castings, machined components, marine propellers, composite structures, large fabricated parts and other components that are hard to inspect automatically with conventional CMM methods.\nPortable and robot-mounted surface gauges complement full-field inspection. They measure roughness, scratches, pits, edge breaks", "f": false}, {"t": "Machine Vision & Automated Defect Inspection", "u": "industrial-precision-manufacturing.html#machine-vision-automated-defect-inspection", "d": "Automated optical inspection finds scratches, contamination, surface defects, missing features and other visual problems, with less manual inspection.", "c": "Industrial & Precision Manufacturing", "k": "Automated optical inspection finds scratches, contamination, surface defects, missing features and other visual problems, with less manual inspection. Machine-vision systems are configured around your part geometry, production rate and defect criteria.\nInspection can be integrated with robotics, conveyors, part handling and production software for inline or near-line quality control.", "f": false}, {"t": "Materials, Coatings & Tribology", "u": "industrial-precision-manufacturing.html#materials-coatings-tribology", "d": "We provide lab systems for testing friction, wear, hardness, adhesion, roughness, coatings, lubricants and other material or surface properties. Contr", "c": "Industrial & Precision Manufacturing", "k": "We provide lab systems for testing friction, wear, hardness, adhesion, roughness, coatings, lubricants and other material or surface properties. Controlled temperature, humidity, vacuum and load reproduce demanding operating environments.\nThese tools support R&amp;D, supplier qualification, product development and quality control for bearings, gears, coatings, polymers, metals and other industrial materials.", "f": false}, {"t": "Precision Laser Processing", "u": "industrial-precision-manufacturing.html#precision-laser-processing", "d": "Laser micromachining cuts, structures, ablates or modifies metals, polymers, glass, ceramics and other materials with minimal mechanical force. Precis", "c": "Industrial & Precision Manufacturing", "k": "Laser micromachining cuts, structures, ablates or modifies metals, polymers, glass, ceramics and other materials with minimal mechanical force. Precision micro-drilling suits nozzles, filters, sieves, fluid-handling parts and other components that need very small holes, high aspect ratios or controlled hole geometry.\nWe support standard laser-processing equipment and custom process development for unusual geometries or materials, including production processes with automated handling.", "f": false}, {"t": "Large & Complex Components", "u": "industrial-precision-manufacturing.html#large-complex-components", "d": "Large industrial parts bring unique metrology and handling challenges. We support inspection for wind-energy components, marine propellers, heavy cast", "c": "Industrial & Precision Manufacturing", "k": "Large industrial parts bring unique metrology and handling challenges. We support inspection for wind-energy components, marine propellers, heavy castings and other large structures where portability, robot reach or full-field measurement matters.\nCustom fixtures and motion systems can be built when a part can&#x27;t be positioned with standard lab equipment.", "f": false}, {"t": "Data Analytics, Optimization & Custom Software", "u": "industrial-precision-manufacturing.html#data-analytics-optimization-custom-software", "d": "Manufacturing improvement depends more and more on how well production data is used. We support optimization, scheduling, equipment-utilization analys", "c": "Industrial & Precision Manufacturing", "k": "Manufacturing improvement depends more and more on how well production data is used. We support optimization, scheduling, equipment-utilization analysis, process monitoring, predictive models, dashboards and automated reporting alongside equipment and automation projects.\nCustom software processes instrument data, generates reports, connects results to production databases and automates repetitive engineering work.", "f": false}, {"t": "From Feasibility to Production", "u": "industrial-precision-manufacturing.html#from-feasibility-to-production", "d": "We combine robots, precision motion, machine vision, metrology, tooling and control software into semi- or fully automated systems. This includes mech", "c": "Industrial & Precision Manufacturing", "k": "We combine robots, precision motion, machine vision, metrology, tooling and control software into semi- or fully automated systems. This includes mechanical design, safety, part handling, recipes, data collection and factory integration.\nProjects move from feasibility testing through design, fabrication, installation and production support.", "f": false}, {"t": "Research & Academia", "u": "research-academia.html", "d": "Electron microscopy, micro- and nanofabrication, optics and photonics research tools, quantum device integration, 2D materials, nanoparticle deposition, probing and custom research systems for universities in Asia.", "c": "Industry", "k": "Electron Microscopy & Advanced Imaging Micro- & Nanofabrication Optics & Photonics Research Quantum & Emerging Device Research 2D Materials, Nanoparticles & Emerging Materials Materials & Surface Characterization Life Sciences & Microfluidics Failure Analysis & Sample Preparation Advanced Electrical & Device Probing Custom Research Systems & Experimental Applications", "f": false}, {"t": "Electron Microscopy & Advanced Imaging", "u": "research-academia.html#electron-microscopy-advanced-imaging", "d": "Scanning and transmission electron microscopy support high-resolution imaging, elemental and structural analysis, biological ultrastructure, tomograph", "c": "Research & Academia", "k": "Scanning and transmission electron microscopy support high-resolution imaging, elemental and structural analysis, biological ultrastructure, tomography, failure analysis and other workflows. Samples span semiconductors, metals, ceramics, polymers, batteries and biological materials.", "f": false}, {"t": "Micro- & Nanofabrication", "u": "research-academia.html#micro-nanofabrication", "d": "We support cleanroom and lab processes including lithography, wafer bonding, nanoimprint, plasma etching, deposition, thermal processing, CMP process ", "c": "Research & Academia", "k": "We support cleanroom and lab processes including lithography, wafer bonding, nanoimprint, plasma etching, deposition, thermal processing, CMP process development and laser micromachining. Equipment is available for research and process development across semiconductors, MEMS, photonics, microfluidics and other microfabricated devices.\nFlexible R&amp;D platforms let researchers explore new materials, substrates and process flows before moving to pilot or production scale.", "f": false}, {"t": "Optics & Photonics Research", "u": "research-academia.html#optics-photonics-research", "d": "We provide interferometric optical metrology, thin-film characterization, precision alignment, optical coating equipment, photonic device processing a", "c": "Research & Academia", "k": "We provide interferometric optical metrology, thin-film characterization, precision alignment, optical coating equipment, photonic device processing and wafer-level optics technologies.\nApplications include precision optics, lasers, waveguides, AR/VR structures, integrated photonics, optical sensors and other experimental optical systems.\nGroups building optical instruments can use active alignment to assemble microscope objectives, laser collimators, telescope-related optics and other multi-element systems. Dynamic interferometry supports adaptive optics, MEMS and measurement in vibration-pro", "f": false}, {"t": "Quantum & Emerging Device Research", "u": "research-academia.html#quantum-emerging-device-research", "d": "Emerging devices often need materials and process flows that are hard to reproduce with conventional semiconductor methods. We support low-temperature", "c": "Research & Academia", "k": "Emerging devices often need materials and process flows that are hard to reproduce with conventional semiconductor methods. We support low-temperature wafer bonding and heterogeneous integration for photonic and quantum-device research, combining silicon, lithium niobate, III-V materials and other specialized platforms.\nThin-film deposition platforms add superconducting films, photonic and sensor layers, piezoelectric materials and wide-bandgap metallization. This gives flexible R&amp;D capability for quantum, RF, MEMS, power-electronics and photonic-device research.\nFor advanced-materials res", "f": false}, {"t": "2D Materials, Nanoparticles & Emerging Materials", "u": "research-academia.html#2d-materials-nanoparticles-emerging-materials", "d": "We support thin-film deposition, low-damage plasma processing and other tools for graphene, 2D materials and emerging functional materials. Controlled", "c": "Research & Academia", "k": "We support thin-film deposition, low-damage plasma processing and other tools for graphene, 2D materials and emerging functional materials. Controlled low-power processing helps where normal plasma conditions would damage delicate layers or contaminate devices.\nVacuum nanoparticle deposition supports research in:\nNanomedicine and biosensorsPhotovoltaics and light harvestingFuel-cell catalysis and electrochemistryEnvironmental purification and surface-enhanced spectroscopies\nSystems offer controlled particle size, composition and co-deposition for exploratory materials research.", "f": false}, {"t": "Materials & Surface Characterization", "u": "research-academia.html#materials-surface-characterization", "d": "Research labs often need several methods to understand materials and surfaces. We support thin-film thickness and optical-property measurement, tribol", "c": "Research & Academia", "k": "Research labs often need several methods to understand materials and surfaces. We support thin-film thickness and optical-property measurement, tribology, roughness and topography, hardness, adhesion, magnetic characterization, electrical measurement and other analytical techniques.\nThese tools serve materials science, coatings, energy research, electronics, biomaterials and many other disciplines.", "f": false}, {"t": "Life Sciences & Microfluidics", "u": "research-academia.html#life-sciences-microfluidics", "d": "For biological and diagnostic research, we support electron microscopy, microfluidic fabrication, nanoimprint, precision glass processing and automate", "c": "Research & Academia", "k": "For biological and diagnostic research, we support electron microscopy, microfluidic fabrication, nanoimprint, precision glass processing and automated inspection. Applications include cell and tissue imaging, biochips, lab-on-chip systems, diagnostic substrates and emerging internal-channel structures in glass.", "f": false}, {"t": "Failure Analysis & Sample Preparation", "u": "research-academia.html#failure-analysis-sample-preparation", "d": "Research and shared facilities may also need tools to investigate failed devices or prepare difficult samples. We support X-ray, acoustic inspection, ", "c": "Research & Academia", "k": "Research and shared facilities may also need tools to investigate failed devices or prepare difficult samples. We support X-ray, acoustic inspection, automated optical inspection, electron microscopy and laser-based sample preparation for SEM, TEM, X-ray microscopy, atom-probe tomography and micromechanical testing. Laser preparation produces targeted cross-sections, site-specific specimens and custom sample geometries.", "f": false}, {"t": "Advanced Electrical & Device Probing", "u": "research-academia.html#advanced-electrical-device-probing", "d": "Flexible probe systems support device research from ultra-low-current and capacitance measurement through high-current, high-voltage power devices, RF", "c": "Research & Academia", "k": "Flexible probe systems support device research from ultra-low-current and capacitance measurement through high-current, high-voltage power devices, RF and sub-THz characterization, optoelectronic testing and magnetic-field-dependent measurement. Temperature-controlled setups extend testing from cryogenic conditions to several hundred degrees Celsius, depending on the application.", "f": false}, {"t": "Custom Research Systems & Experimental Applications", "u": "research-academia.html#custom-research-systems-experimental-applications", "d": "Novel research doesn&#x27;t always fit standard equipment. We help evaluate new applications and develop custom fixtures, sample holders, motion, hand", "c": "Research & Academia", "k": "Novel research doesn&#x27;t always fit standard equipment. We help evaluate new applications and develop custom fixtures, sample holders, motion, handling, machine vision, integrated experimental systems and data-processing or reporting software.\nThis flexibility supports exploratory work and gives you a path to repeatable lab, pilot or future production workflows as your application matures.", "f": false}, {"t": "All industries", "u": "industries.html", "d": "Overview of every industry Dymek serves.", "c": "Page", "k": "industries sectors", "f": true}, {"t": "Metrology Equipment Sales", "u": "metrology-equipment-sales.html", "d": "Buy metrology, inspection and process equipment from global technology partners with local application support, demos, installation and training across 8 Asian markets.", "c": "Service", "k": "Our portfolio covers the measurement and inspection needs of advanced manufacturing:\nInterferometric and dynamic optical metrologyThin-film thickness and optical-property measurementNon-contact 3D surface and topography metrologyX-ray/CT, scanning acoustic microscopy and automated optical inspection Application review. We start with your part, process and specification, not a catalogue.Feasibility trials. Where possible, we arrange sample measurements or demos so you can see results on your own parts.Clear proposals. We explain options and trade-offs in plain language, so your engineering and p Since 1989, we have worked as the link between global technology providers and industrial customers across Asia. You get local language support, local time zones and engineers who understand both the technology and your production reality.", "f": true}, {"t": "Custom System Integration", "u": "custom-system-integration.html", "d": "Custom inspection and process systems built around your part: robotics, precision motion, machine vision, fixtures, controls, recipes, data collection and factory integration, from feasibility to production.", "c": "Service", "k": "Metrology and inspection instrumentsRobots and precision motion systemsMachine vision and automated handlingCustom fixtures, tooling and safety enclosuresControl systems, measurement recipes and pass/fail logicData collection, reporting and connection to factory databases and quality systems Feasibility testing. We test whether the measurement or process works on your real parts.Measurement and process development. We define the method, recipe and acceptance criteria with your engineers.System design. Mechanical design, motion, handling, safety and software are specified around your lin Custom integration appears across our industries: automated 3D inspection of aerospace and industrial parts, optical assembly cells, advanced packaging assembly, failure-analysis workflows, display repair and photovoltaic laser processing.", "f": true}, {"t": "Calibration & Service", "u": "calibration-service.html", "d": "Installation, commissioning, calibration, preventive maintenance, repair, refurbishment, relocation and spare-parts support for metrology and semiconductor equipment across Asia.", "c": "Service", "k": "Installation and commissioning of new and relocated systemsCalibration and preventive maintenance to keep measurements accurate and repeatableField service and troubleshooting from engineers based in the regionRepair and refurbishment of selected subsystems, including vacuum pumps, RF generators and We coordinate closely with equipment manufacturers and specialist service partners. In Malaysia, for example, EV Group and Dymek operate the joint venture EV Group Malaysia Dymek Sdn. Bhd., which handles equipment installation, technical service, spare parts and process development support. Research fabs, MEMS lines, power semiconductor plants and specialty manufacturers often rely on mature tools. We help you decide when refurbishment, subsystem replacement or full replacement makes most sense.", "f": true}, {"t": "Services", "u": "services.html", "d": "Equipment sales, integration and service support.", "c": "Page", "k": "service support", "f": true}, {"t": "About Dymek", "u": "about.html", "d": "Our history, mission, vision and team.", "c": "Page", "k": "history 1989 mission vision team", "f": true}, {"t": "Our Principals", "u": "partners.html", "d": "52 equipment makers we represent, including EV Group, 4D Technology, 3D-Micromac and Thermo Fisher Scientific (FEI).", "c": "Page", "k": "3D-Micromac Precision laser micromachining 4D Technology Optical surface & wavefront metrology Amerimade Technology Wet processing & chemical handling systems AP&S International Semiconductor wet processing & wafer cleaning Beneq Atomic layer deposition systems Boffotto Semiconductor Plasma etching & surface treatment Cortex Robotics Automated optical inspection & machine vision Daeil Systems Precision vibration isolation Delcom Instruments Non-contact sheet resistance measurement DexForce AI-powered 3D vision & robotics Elveflow Precision microfluidic control & measurement EV Group (EVG) Wafer bonding & advanced lithography FEI / Thermo Fisher Scientific Electron microscopy & nanoscale analysis Film Sense Compact ellipsometry & film measurement First Nano CVD & nanomaterial growth GigaScan Technologies High-resolution 3D vision & inspection Herz Precision vibration isolation systems Herzan Active vibration & acoustic isolation HiSOL Semiconductor probing & device testing ilis Optical stress & birefringence measurement i-Photonics Precision optical thin-film coating Jandel Engineering Four-point probe resistivity measurement JFP Microtechnic Precision die & wire bonding KLA MicroSense Magnetic & precision measurement Langer EMV-Technik EMC testing & electronic diagnostics LESCO Specialized manufacturing equipment Lynxx Laser machining for optical components Marposs / Solarius Precision 3D surface & optical metrology Mecademic Ultra-compact precision industrial robotics Microview High-precision die bonding & assembly MKS Instruments Semiconductor process control & subsystems Moorfield Nanotechnology Thin-film deposition & plasma processing Nanotronics Inspection Systems AI-powered automated optical inspection n&k Technology Thin-film & critical-dimension metrology NYLI Metrology Technical cleanliness & particle analysis Opto-Alignment Optical alignment, assembly & metrology Otsuka Electronics Optical spectroscopy & material characterization PicoQuant Single-photon & time-resolved measurement PLSINTEC Advanced precision metrology solutions Polyteknik AS Precision PVD & thin-film metallization P&TECH 2000 Semiconductor & solar processing furnaces Raditech Precision surface & dimensional metrology RedLux Automated optical surface inspection Rtec Instruments Tribology & surface characterization SEC Co., Ltd. Electron microscopy & X-ray inspection Sonix Scanning acoustic microscopy Stefan Mayer Instruments Magnetic field measurement & compensation Swiss Cluster Advanced ALD & PVD deposition Tau Science Photovoltaic cell & module inspection The Scatter Works Optical scatterometry & surface measurement ThetaMetrisis Thin-film thickness & optical properties Tystar Diffusion, oxidation & LPCVD furnaces", "f": true}, {"t": "Contact us", "u": "contact.html", "d": "Send a message or find an office.", "c": "Page", "k": "contact email phone offices address Hong Kong Beijing Shanghai Dongguan Hsinchu Penang Singapore Pathum Thani Hanoi Manila (Muntinlupa)", "f": true}, {"t": "Careers", "u": "careers.html", "d": "Open roles and how to apply.", "c": "Page", "k": "jobs careers engineer hiring apply thailand taiwan hsinchu application engineer fae sales operations assistant kuala lumpur", "f": true}, {"t": "Insights", "u": "blog.html", "d": "All articles.", "c": "Page", "k": "blog articles insights", "f": true}, {"t": "What Is Hybrid Bonding? Wafer-to-Wafer vs Die-to-Wafer Explained", "u": "hybrid-bonding-explained.html", "d": "Hybrid bonding joins two chips through copper pads and dielectric at the same time, with no solder bumps. Here is how it works, where it is used and what it takes to get yield.", "c": "Article", "k": "hybrid bonding wafer-to-wafer bonding die-to-wafer bonding HBM hybrid bonding 3D integration In a hybrid bond, two surfaces are joined in one step through two materials at once:\nDielectric to dielectric, usually silicon oxide or a similar film, which bonds first at room temperatureCopper to copper, through pads embedded in that dielectric, which form a metal connection during a later anneal\nBecause there is no solder bump, the pads can be much smaller and closer together. Conventional micro-bumps typically sit at pitches of tens of microns. Hybrid bonding works at single-digit micron pitch and below, which means many more connections per square millimeter, shorter signal paths and lower power per bit. Wafer-to-wafer bonding joins two full wafers. It offers high alignment accuracy and throughput, and it is well established in stacked CMOS image sensors and some memory designs. The ", "f": true}, {"t": "Co-Packaged Optics (CPO) Explained: Why AI Data Centers Are Moving Optics onto the Package", "u": "co-packaged-optics-explained.html", "d": "Nvidia and Broadcom are now shipping co-packaged optics switches. Here is what CPO is, why it saves power, and what makes it hard to manufacture.", "c": "Article", "k": "co-packaged optics CPO silicon photonics optical I/O AI data center interconnect In a conventional switch, the switch ASIC sends electrical signals across the circuit board to pluggable transceivers. Each transceiver converts them to light.\nIn CPO, optical engines sit in the same package as the switch ASIC. The electrical path shrinks from many centimeters to a few millimeters. That lowers power per bit and latency and frees space on the front panel. According to a TrendForce report covered by Electronics360 in July 2026:\nNvidia and Broadcom have both entered volume production of CPO switches.Broadcom&#x27;s Bailly CPO switch reduces power consumption by up to 70% compared with conventional pluggable optics, and has been validated with hyperscalers such as Meta.Nvidia&#x27;s Spectrum-X CPO switch, developed with TSMC&#x27;s COUPE packaging technology, offers up to 400 ", "f": true}, {"t": "How Laser Sample Preparation Speeds Up Semiconductor Failure Analysis", "u": "laser-sample-preparation-failure-analysis.html", "d": "Failure analysis often waits on sample preparation. Laser-based preparation removes bulk material fast, so FIB time goes to the final, precise step.", "c": "Article", "k": "semiconductor failure analysis sample preparation FIB cross section advanced package failure analysis laser ablation Typical ways to reach a buried target are:\nMechanical grinding and polishing. Low equipment cost, but slow, operator-dependent and prone to smearing, cracking or deforming soft materials like solder.Focused ion beam (FIB). Very precise, but gallium FIB removes material slowly. Large-volume removal can take many hours.Plasma FIB (PFIB). Much faster than gallium FIB, but still costly per cubic millimeter when targets are deep or wide.\nAs packages grow larger and more 3D, with stacked dies, interposers and hybrid-bonded interfaces, the volume of material to remove keeps growing. Laser ablation removes large volumes of material quickly and without mechanical contact. It is used to:\nCut large-area package cross-sectionsExpose flip-chip bumps, solder joints and solder balls without deformationRe", "f": true}, {"t": "Thin Film Thickness Measurement: Reflectometry vs Ellipsometry vs Interferometry", "u": "thin-film-thickness-measurement.html", "d": "Three optical methods dominate thin-film measurement. Here is what each one measures, where it shines and how to choose.", "c": "Article", "k": "thin film thickness measurement spectral reflectometry ellipsometry optical interferometry film thickness gauge How it works. Light shines on the film at or near normal incidence. Reflections from the top and bottom of the film interfere, creating a pattern of peaks and valleys across wavelengths. Software fits that spectrum to a model to find thickness, and often refractive index (n) and extinction coefficient (k).\nStrengths\nFast, simple and affordableWorks from a few nanometers up to very thick films, depending on the systemEasy to automate for mapping and production checksSmall-spot versions can measure patterned regions\nLimits\nVery thin films and complex stacks are harder to separateNeeds reasonable knowledge of the materials\nTypical uses. Resists, oxides, nitrides, hard coats, AR coatings, polymer films and production monitoring. How it works. Light hits the sample at an angle. The instrument m", "f": true}, {"t": "SiC and GaN Power Device Manufacturing: Key Process, Test and Inspection Challenges", "u": "sic-gan-power-device-manufacturing.html", "d": "Wide-bandgap power devices power EV inverters and fast chargers. Their materials make every process step harder. Here is where the challenges are.", "c": "Article", "k": "SiC power device manufacturing GaN power devices SiC wafer dicing laser annealing SiC EV power electronics SiC is extremely hard and brittle. It is close to diamond in hardness, which makes grinding, polishing and dicing slow and wear-intensive.Crystal defects matter more. Defects in SiC substrates and epitaxy can kill devices or degrade them over time.GaN is often grown on other substrates, such as silicon, which creates stress, wafer bow and defect challenges.Devices run hot and at high voltage, so packages and interconnects face severe thermal and electrical stress. Wafer thinning and dicing. Thin wafers reduce on-resistance, but thin SiC is fragile. Blade dicing of SiC is slow and can cause chipping. Laser-based separation methods can improve edge quality, speed and mechanical strength.\nBackside contacts. After thinning, SiC devices need a low-resistance ohmic contact on the backside. Selec", "f": true}, {"t": "Southeast Asia's Semiconductor Growth: What It Means for Equipment Buyers", "u": "southeast-asia-semiconductor-equipment.html", "d": "Southeast Asia is moving from assembly toward advanced packaging, design and specialty fabs. Here is what that shift means when you choose equipment and support.", "c": "Article", "k": "Southeast Asia semiconductor industry Malaysia semiconductor Penang semiconductor semiconductor equipment supplier Asia National Semiconductor Strategy Intel opened its first overseas assembly plant in Penang in 1972. Since then, Malaysia has become a global center for back-end manufacturing. According to a 2024 article published by the Malaysian Investment Development Authority (MIDA):\nMalaysia holds about 13% of global semiconductor testing and packaging.The industry accounts for about 25% of Malaysia&#x27;s GDP.The National Semiconductor Strategy starts with RM25 billion in public funding. It aims to attract RM500 billion of investment, train 60,000 chip engineers and build at least 10 Malaysian companies in design and advanced packaging. Across the region, manufacturers are diversifying supply chains and investing in new capacity. Singapore has deep strengths in wafer fabrication and equipment. Thailand, Vietnam and the Philippines ar", "f": true}, {"t": "Free Engineering Tools", "u": "tools.html", "d": "Free calculators: thin-film thickness, unit converter, dies per wafer, method finder, cleanroom ISO class.", "c": "Tool", "k": "tools calculator free"}, {"t": "Thin-Film Thickness Calculator", "u": "thin-film-calculator.html", "d": "Reflectance spectrum and thickness from interference peaks.", "c": "Tool", "k": "film thickness reflectance interference calculator"}, {"t": "Engineering Unit Converter", "u": "unit-converter.html", "d": "µm, nm, Å, Torr, mbar, Pa, psi, °C, K, Ra and Rq.", "c": "Tool", "k": "unit converter torr pascal micron angstrom roughness"}, {"t": "Dies per Wafer & Yield Calculator", "u": "dies-per-wafer-calculator.html", "d": "Gross dies, wafer map and yield with Poisson, Murphy or Seeds models.", "c": "Tool", "k": "dies per wafer yield defect density wafer map"}, {"t": "Measurement Method Finder", "u": "measurement-method-finder.html", "d": "Answer four questions to find a suitable metrology or inspection method.", "c": "Tool", "k": "measurement method metrology inspection finder"}, {"t": "Cleanroom ISO Class Calculator", "u": "cleanroom-class-calculator.html", "d": "ISO 14644-1 particle limits, sampling locations and class check.", "c": "Tool", "k": "cleanroom iso 14644 particle class"}, {"t": "Brochures", "u": "brochures.html", "d": "Read Dymek brochures online, including n&k Technology for Data Storage Manufacturing.", "c": "Page", "k": "brochure n&k data storage read online"}, {"t": "Demo & Sample Testing", "u": "sample-testing.html", "d": "Send a sample for a feasibility test or book a demo.", "c": "Page", "k": "demo sample test feasibility"}, {"t": "Events & Trade Shows", "u": "events.html", "d": "SEMICON China, Southeast Asia, Taiwan, Japan and more. Book a meeting.", "c": "Page", "k": "events trade shows semicon exhibition"}, {"t": "Case Studies", "u": "case-studies.html", "d": "EV Group joint venture and 3D-Micromac trade agency in Asia.", "c": "Page", "k": "case study evg 3d-micromac"}, {"t": "Request a Quote", "u": "quote.html", "d": "One quote request for one or more principals.", "c": "Page", "k": "quote price quotation rfq"}];